271	const BRAND = { blue: "#3b82f6", purple: "#8a70fb", bg: "#0a101f", card: "#111a30" };
272	
273	/**
274	 * Shared responsive email shell (inline styles for client compatibility).
275	 * Kept for the synchronous, code-rendered `emails.*` templates below and any
276	 * existing importers. DB-template sends use `wrapEmail` in `lib/email-render`.
277	 */
278	export function layout(title: string, body: string): string {
279	  // Delegate to the shared premium shell so every email is consistent.
280	  const heading = title
281	    ? `<h1 style="margin:0 0 16px;font-size:21px;font-weight:700;color:#ffffff;line-height:1.25;">${title}</h1>`
282	    : "";
283	  return wrapEmail(`${heading}<div>${body}</div>`);
284	}
285	
286	export function button(href: string, label: string): string {
287	  return emailButton(href, label);
288	}
289	
290	// ---- Transactional templates ----
291	//
292	// The full transactional catalog lives in `lib/email-templates.ts` (30+
293	// templates, all composed from the shared inline-styled components). It is
294	// re-exported here as `emails` so every existing call site — `import { emails }
295	// from "@/lib/mailer"` — keeps working unchanged. Each entry returns
296	// `{ template, subject, html }`; the six original signatures are preserved.
297	export type { BuiltEmail };
298	
299	// ===========================================================================
300	// Card billing & dunning templates
301	//
302	// Renewals apply wallet credit first, then auto-charge the customer's saved
303	// card for the remainder. When that charge fails we retry on day 1, 3 and 5 and
304	// only suspend once the retries are exhausted. These templates carry that flow.
305	//
306	// They live here rather than in `lib/email-templates.ts` only because this file
307	// is the one owned by the card-billing change; they are built with the same
308	// `build()` shape and the same shared components, so they render identically to
309	// the rest of the catalog.
310	// ===========================================================================
311	
312	/**
313	 * Number of automatic retries in the dunning sequence (day 1, day 3, day 5).
314	 * `paymentRetryFailed` uses it to tell the customer how many attempts are left,
315	 * so the worker's retry schedule and this copy must agree.
316	 */
317	export const DUNNING_RETRY_ATTEMPTS = 3;
318	
319	/**
320	 * Same composition helper as `lib/email-templates.ts` (which keeps its copy
321	 * module-private): eyebrow → heading → body blocks → single CTA → optional
322	 * footnote, wrapped with a preheader by the shared shell.
323	 */
324	function build(opts: {
325	  template: string;
326	  subject: string;
327	  preheader: string;
328	  eyebrow?: string;
329	  accent?: Accent;
330	  heading: string;
331	  blocks: string[];
332	  cta?: { href: string; label: string; accent?: Accent };
333	  note?: string;
334	}): BuiltEmail {
335	  const parts: string[] = [];
336	  if (opts.eyebrow) parts.push(emailEyebrow(opts.eyebrow, opts.accent ?? "violet"));
337	  parts.push(emailHeading(opts.heading));
338	  parts.push(...opts.blocks);
339	  if (opts.cta) parts.push(emailButton(opts.cta.href, opts.cta.label, opts.cta.accent ?? "violet"));
340	  if (opts.note) parts.push(emailNote(opts.note));
341	  return {
342	    template: opts.template,
343	    subject: opts.subject,
344	    html: wrapEmail(parts.join("\n"), { preheader: opts.preheader }),
345	  };
346	}
