31	function parseCsv(text: string): { headers: string[]; rows: string[][] } {
32	  const records: string[][] = [];
33	  let field = "";
34	  let row: string[] = [];
35	  let inQuotes = false;
36	  const src = text.replace(/\r\n?/g, "\n");
37	
38	  for (let i = 0; i < src.length; i++) {
39	    const c = src[i];
40	    if (inQuotes) {
41	      if (c === '"') {
42	        if (src[i + 1] === '"') {
43	          field += '"';
44	          i++;
45	        } else {
46	          inQuotes = false;
47	        }
48	      } else {
49	        field += c;
50	      }
51	    } else if (c === '"') {
52	      inQuotes = true;
53	    } else if (c === ",") {
54	      row.push(field);
55	      field = "";
56	    } else if (c === "\n") {
57	      row.push(field);
58	      records.push(row);
59	      row = [];
60	      field = "";
61	    } else {
62	      field += c;
63	    }
64	  }
65	  // Flush trailing field/row.
66	  if (field.length > 0 || row.length > 0) {
67	    row.push(field);
68	    records.push(row);
69	  }
70	
71	  const nonEmpty = records.filter((r) => r.some((v) => v.trim() !== ""));
72	  if (nonEmpty.length === 0) return { headers: [], rows: [] };
73	  const headers = nonEmpty[0].map((h) => h.trim().toLowerCase());
74	  return { headers, rows: nonEmpty.slice(1) };
75	}
