205	/**
206	 * Paste-a-CSV import. Parses server-side and creates Business (+ optional
207	 * Contact) rows. No scraping, no enrichment — exactly the rows pasted. Contacts
208	 * de-dupe against the unique email. Returns a summary in the error/ok channel.
209	 */
210	export async function importBusinessesCsv(_prev: ActionState, formData: FormData): Promise<ActionState> {
211	  await requireArea("platform");
212	
213	  const csv = String(formData.get("csv") ?? "");
214	  const recordConsentAll = formData.get("recordConsent") === "on" || formData.get("recordConsent") === "true";
215	  if (!csv.trim()) return { error: "Paste some CSV rows first." };
216	
217	  const { headers, rows } = parseCsv(csv);
218	  if (headers.length === 0 || rows.length === 0) {
219	    return { error: "Could not find a header row and at least one data row." };
220	  }
221	  const cols = headers.map((h) => HEADER_ALIASES[h] ?? "");
222	  if (!cols.includes("name")) {
223	    return { error: "CSV needs at least a 'name' (business name) column." };
224	  }
225	
226	  let created = 0;
227	  let contactsCreated = 0;
228	  let skipped = 0;
229	
230	  for (const r of rows) {
231	    const rec: Record<string, string> = {};
232	    cols.forEach((field, i) => {
233	      if (field) rec[field] = (r[i] ?? "").trim();
234	    });
235	    const name = (rec.name ?? "").trim();
236	    if (!name) {
237	      skipped++;
238	      continue;
239	    }
240	    try {
241	      const business = await db.business.create({
242	        data: {
243	          name: name.slice(0, 160),
244	          category: (rec.category ?? "").slice(0, 120),
245	          businessType: (rec.businessType ?? "").slice(0, 120),
246	          website: (rec.website ?? "").slice(0, 200),
247	          phone: (rec.phone ?? "").slice(0, 60),
248	          addressLine: (rec.addressLine ?? "").slice(0, 200),
249	          city: (rec.city ?? "").slice(0, 120),
250	          region: (rec.region ?? "").slice(0, 120),
251	          country: (rec.country ?? "").slice(0, 120),
252	          companySize: (rec.companySize ?? "").slice(0, 60),
253	          source: "csv",
254	        },
255	      });
256	      created++;
257	
258	      const email = normalizeEmail(rec.email);
259	      if (email && emailSchema.safeParse(email).success) {
260	        const clash = await db.contact.findUnique({ where: { email }, select: { id: true } });
261	        if (!clash) {
262	          const contact = await db.contact.create({
263	            data: {
264	              businessId: business.id,
265	              fullName: (rec.fullName ?? "").slice(0, 160),
266	              title: (rec.title ?? "").slice(0, 120),
267	              email,
268	            },
269	          });
270	          contactsCreated++;
271	          if (recordConsentAll) {
272	            await db.consentRecord.create({
273	              data: { contactId: contact.id, basis: "LEGITIMATE_INTEREST", source: "csv import" },
274	            });
275	          }
276	        }
277	      }
278	    } catch (err) {
279	      await logEvent("error", "coldemail.business.import", { message: String(err) });
280	      skipped++;
281	    }
282	  }
283	
284	  revalidatePath("/admin/coldemail/businesses");
285	  revalidatePath("/admin/coldemail");
286	  return { ok: true, error: `Imported ${created} businesses and ${contactsCreated} contacts. ${skipped} row(s) skipped.` };
287	}
