481	/**
482	 * Dry-run a DRAFT campaign: for its list, how many recipients would be
483	 * SUPPRESSED, how many lack a recorded consent basis, and how many are
484	 * sendable — WITHOUT sending, scheduling, or writing anything. Blocked (with the
485	 * missing-requirement list) if the brand fails requireBrandCompliance.
486	 */
487	export async function previewCampaign(campaignId: string): Promise<CampaignPreview | { error: string }> {
488	  await requireArea("platform");
489	
490	  const campaign = await db.coldCampaign.findUnique({
491	    where: { id: campaignId },
492	    include: { brand: true },
493	  });
494	  if (!campaign) return { error: "Campaign not found." };
495	
496	  const missing = requireBrandCompliance(campaign.brand);
497	  if (missing.length > 0) {
498	    return {
499	      blocked: true,
500	      missingRequirements: missing.map((m) => m.label),
501	      total: 0,
502	      suppressed: 0,
503	      missingConsent: 0,
504	      sendable: 0,
505	    };
506	  }
507	
508	  const members = await db.emailListMember.findMany({
509	    where: { listId: campaign.listId },
510	    select: {
511	      contact: {
512	        select: { id: true, email: true, consentRecords: { select: { id: true }, take: 1 } },
513	      },
514	    },
515	  });
516	
517	  const suppressions: SuppressionLike[] = await db.suppression.findMany({
518	    where: { OR: [{ scope: "GLOBAL" }, { scope: "BRAND", brandId: campaign.brandId }] },
519	    select: { email: true, domain: true, scope: true, brandId: true },
520	  });
521	
522	  let suppressed = 0;
523	  let missingConsent = 0;
524	  let sendable = 0;
525	  for (const m of members) {
526	    const email = m.contact.email;
527	    if (isSuppressed(email, campaign.brandId, suppressions)) {
528	      suppressed++;
529	      continue;
530	    }
531	    if (m.contact.consentRecords.length === 0) {
532	      missingConsent++;
533	      continue;
534	    }
535	    sendable++;
536	  }
537	
538	  return {
539	    blocked: false,
540	    missingRequirements: [],
541	    total: members.length,
542	    suppressed,
543	    missingConsent,
544	    sendable,
545	  };
546	}
