552	const SUPPRESSION_REASONS = ["UNSUBSCRIBE", "BOUNCE", "COMPLAINT", "MANUAL"] as const;
553	
554	export async function addSuppression(_prev: ActionState, formData: FormData): Promise<ActionState> {
555	  await requireArea("platform");
556	  const rawValue = String(formData.get("value") ?? "").trim().toLowerCase();
557	  const kind = String(formData.get("kind") ?? "email"); // "email" | "domain"
558	  const reasonRaw = String(formData.get("reason") ?? "MANUAL");
559	  const reason = (SUPPRESSION_REASONS as readonly string[]).includes(reasonRaw)
560	    ? (reasonRaw as (typeof SUPPRESSION_REASONS)[number])
561	    : "MANUAL";
562	  if (!rawValue) return { error: "Enter an email address or domain." };
563	
564	  const isEmail = kind === "email";
565	  if (isEmail && !emailSchema.safeParse(rawValue).success) return { error: "Enter a valid email address." };
566	  if (!isEmail && !/^[a-z0-9.-]+\.[a-z]{2,}$/.test(rawValue)) return { error: "Enter a valid domain." };
567	
568	  const where = isEmail
569	    ? { scope: "GLOBAL" as const, email: rawValue }
570	    : { scope: "GLOBAL" as const, domain: rawValue };
571	  const existing = await db.suppression.findFirst({ where, select: { id: true } });
572	  if (!existing) {
573	    await db.suppression.create({
574	      data: isEmail
575	        ? { scope: "GLOBAL", email: rawValue, reason }
576	        : { scope: "GLOBAL", domain: rawValue, reason },
577	    });
578	  }
579	  revalidatePath("/admin/coldemail/suppression");
580	  revalidatePath("/admin/coldemail");
581	  return { ok: true };
582	}
