592	/** Bulk import suppression entries (one email or domain per line, or CSV). */
593	export async function importSuppressionCsv(_prev: ActionState, formData: FormData): Promise<ActionState> {
594	  await requireArea("platform");
595	  const text = String(formData.get("csv") ?? "");
596	  if (!text.trim()) return { error: "Paste some addresses or domains first." };
597	
598	  const tokens = text
599	    .split(/[\n,;\s]+/)
600	    .map((t) => t.trim().toLowerCase())
601	    .filter(Boolean);
602	
603	  let added = 0;
604	  let skipped = 0;
605	  for (const t of tokens) {
606	    const isEmail = t.includes("@");
607	    const valid = isEmail ? emailSchema.safeParse(t).success : /^[a-z0-9.-]+\.[a-z]{2,}$/.test(t);
608	    if (!valid) {
609	      skipped++;
610	      continue;
611	    }
612	    const where = isEmail ? { scope: "GLOBAL" as const, email: t } : { scope: "GLOBAL" as const, domain: t };
613	    const existing = await db.suppression.findFirst({ where, select: { id: true } });
614	    if (existing) {
615	      skipped++;
616	      continue;
617	    }
