234	/**
235	 * Allocate a vmid for a brand-new server, refusing any id that still owns backup
236	 * archives from a previous tenant (see `pickProvisionVmid` for the incident).
237	 *
238	 * If the archive listing cannot be read we do NOT silently fall back to the raw
239	 * `nextVmid()` — that is the exact behaviour that leaks a previous tenant's data,
240	 * and a provision that fails is recoverable while a cross-tenant disclosure is
241	 * not. The job retries; an operator sees why.
242	 */
243	async function allocateFreshVmid(conn: any): Promise<number> {
244	  const candidate = await conn.nextVmid();
245	  const archived = await archivedVmids(conn);
246	
247	  // Ids already in use, so skipping forward cannot land on a live VM. Read
248	  // cluster-wide (qemu + lxc); fall back to this node's qemu list.
249	  let taken = new Set<number>();
250	  try {
251	    const res: any[] = await conn.get("/cluster/resources", { type: "vm" });
252	    for (const r of res ?? []) if (Number.isInteger(r?.vmid)) taken.add(r.vmid);
253	  } catch {
254	    const vms: any[] = await conn.get(`/nodes/${conn.node}/qemu`);
255	    taken = new Set((vms ?? []).map((v: any) => Number(v?.vmid)).filter(Number.isInteger));
256	  }
257	
258	  const { vmid, skipped } = pickProvisionVmid({ candidate, takenVmids: taken, archivedVmids: archived });
259	  if (skipped.length > 0) {
260	    console.warn(
261	      `[worker] vmid ${skipped.join(", ")} skipped for provisioning — still holds backup archives ` +
262	        `from a previous server; allocated ${vmid} instead`
263	    );
264	  }
265	  return vmid;
266	}
