479	/**
480	 * Tear down a VM. Idempotent and verified — see `destroyVmIdempotent` in
481	 * lib/proxmox.ts for the incident and the ladder. The bare version of this
482	 * function threw on an already-absent VM, which is what made a retried REINSTALL
483	 * destroy a customer's server permanently.
484	 */
485	async function destroyVm(conn: any, vmid: number): Promise<DestroyOutcome> {
486	  const host: VmDestroyHost = {
487	    probe: async (id) => {
488	      try {
489	        await conn.vmStatus(id);
490	        return "present";
491	      } catch (e) {
492	        // Only a vmid-anchored "config does not exist" proves absence. Anything
493	        // else (auth, network, a locked node) is genuinely unknown and must not
494	        // be read as "already gone".
495	        return isVmAbsentError(e, id) ? "absent" : "unknown";
496	      }
497	    },
498	    stop: async (id) => {
499	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${id}/status/stop`, {});
500	      await conn.waitForTask(stopUpid);
501	    },
502	    destroy: async (id) => {
503	      const delUpid = await conn.del(`/nodes/${conn.node}/qemu/${id}`, {
504	        "destroy-unreferenced-disks": 1,
505	        purge: 1,
506	      });
507	      await conn.waitForTask(delUpid, 600_000);
508	    },
509	  };
510	  return destroyVmIdempotent(host, vmid);
511	}
