513	async function remove(job: Job) {
514	  const server = await loadServer(job);
515	  const { conn } = await nodeFor(server);
516	  if (!SANDBOX && server.vmid) {
517	    // `destroyVm` is now idempotent and VERIFIES the VM is gone before returning,
518	    // so the absent case no longer needs to be caught here at all. The catch that
519	    // remains is narrowed to this vmid: it used to swallow any error containing
520	    // "does not exist", which also matches `storage 'vmdata' does not exist` and
521	    // `volume ... does not exist` — errors that mean the VM is very much still
522	    // running. On one of those the handler proceeded to delete the Server row and
523	    // every Volume row pinned to it, leaving a live VM with no database record:
524	    // invisible to billing, invisible to the panel, still holding the customer's
525	    // data and impossible to reach through any surface we own.
526	    try {
527	      await destroyVm(conn, server.vmid);
528	    } catch (e: any) {
529	      if (!isVmAbsentError(e, server.vmid)) throw e;
530	    }
531	    // Best-effort: remove the per-server cloud-init snippet
532	    await unlink(`${SNIPPET_DIR}/nxeon-${server.vmid}.yaml`).catch(() => {});
533	  }
534	  // Return any dedicated IP to the pool (deletes the OVH Virtual MAC).
535	  if (!SANDBOX) await releaseDedicatedIp(server.id).catch((e) => console.error("[worker] release dedicated IP failed", e));
536	  // Any block-storage volume disk (vm-<vmid>-disk-N) was purged with the VM above.
537	  // Volume.server is SetNull, so the rows would otherwise survive with a dead
538	  // diskName and keep billing forever. Remove them and notify the owner. (The
539	  // reinstall guard already blocks the accidental case; a full server delete is an
540	  // intentional teardown, so we drop the volumes with it.)
541	  const orphanVolumes = await db.volume.findMany({ where: { serverId: server.id } });
542	  if (orphanVolumes.length > 0) {
543	    await db.volume.deleteMany({ where: { serverId: server.id } });
544	    for (const v of orphanVolumes) {
545	      await notify(
546	        v.userId,
547	        `Volume "${v.name}" was removed`,
548	        `${v.sizeGB} GB block storage was deleted along with server ${server.hostname}. Billing for it has stopped.`,
549	        "/dashboard/volumes",
550	      ).catch(() => {});
551	    }
552	  }
553	  // Detach this DELETE job (and any siblings) from the server FIRST, otherwise the
554	  // server.delete cascade removes THIS running Job row — the success-path
555	  // `job.update({id})` then throws P2025 and escapes runJob. Null serverId instead.
556	  await db.job.updateMany({ where: { serverId: server.id }, data: { serverId: null } });
557	  await db.server.delete({ where: { id: server.id } });
558	  // Best-effort BY NECESSITY: the server row is gone, so a throw here re-queues
559	  // DELETE, which then dies on "Server not found" and the sync is never retried
560	  // (H5's aggravating factor). The failure is logged in full rather than hidden.
561	  if (!SANDBOX) await syncPortForwardsBestEffort(`delete ${server.hostname}`);
562	}
