564	async function reinstall(job: Job) {
565	  const server = await loadServer(job);
566	  if (SANDBOX) {
567	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
568	    await notify(
569	      server.userId,
570	      `Server ${server.hostname} reinstalled (sandbox)`,
571	      "The sandbox server was reinstalled (no real VM was touched).",
572	      `/dashboard/servers/${server.id}`
573	    );
574	    return;
575	  }
576	  // DATA SAFETY (critical): a reinstall destroys the VM, and `destroyVm` runs
577	  // `qm destroy` with { "destroy-unreferenced-disks": 1, purge: 1 } — which wipes
578	  // EVERY disk the vmid owns, including attached block-storage Volume disks
579	  // (scsi1+, `vmdata:vm-<vmid>-disk-N`). A disk named `vm-<vmid>-disk-N` is owned
580	  // by that vmid, and both purge and the default destroy (which removes disks
581	  // referenced in config, incl. detached `unusedN` entries) delete it; there is no
582	  // Proxmox API to selectively spare it, and the reinstall re-clones onto the SAME
583	  // vmid, so we cannot GUARANTEE such a disk survives the destroy. Rather than risk
584	  // wiping a customer's data, BLOCK the reinstall until the volume(s) are detached.
585	  // Detaching moves the disk to an "unused" entry (data preserved on storage) and it
586	  // can be re-attached after the reinstall. This runs BEFORE any status change or
587	  // destructive call, so a blocked reinstall touches nothing.
588	  //
589	  // Match on `serverId` ALONE — NOT `status: "ATTACHED"`. Detaching keeps
590	  // `serverId` set (see worker/volumes.ts) so the volume can be re-attached, and
591	  // the disk remains owned by this vmid as an `unusedN` entry. PVE's destroy_vm
592	  // passes `include_unused => 1`, so it frees those too. Filtering on ATTACHED
593	  // let the worst path through: fill a volume, Detach (the UI says "Data is
594	  // preserved."), Reinstall — guard sees nothing attached, purge takes the data.
595	  // Detaching is therefore NOT sufficient protection, and telling the customer to
596	  // detach was wrong advice; they must delete the volume (which destroys just
597	  // that disk, deliberately) or move it to another server first.
598	  const pinnedVolumes = await db.volume.findMany({
599	    where: { serverId: server.id },
600	  });
601	  // Sandbox volumes have no real disk, so they cannot be purged and must not block.
602	  const realPinned = pinnedVolumes.filter(
603	    (v) => !(typeof v.diskName === "string" && v.diskName.startsWith("sandbox:"))
604	  );
605	  if (realPinned.length > 0) {
606	    const names = realPinned.map((v) => `"${v.name}"`).join(", ");
607	    throw new Error(
608	      `Remove your data volume(s) before reinstalling to protect their data: ${names}. ` +
609	        `Reinstalling purges every disk this server owns — including detached volumes ` +
610	        `that are still assigned to it — and that cannot be undone.`
611	    );
612	  }
613	
614	  const { conn } = await nodeFor(server);
615	  await db.server.update({ where: { id: server.id }, data: { status: "REINSTALLING" } });
616	  if (server.vmid) await destroyVm(conn, server.vmid);
617	  await provision(job);
618	}
