620	async function suspend(job: Job, unsuspend: boolean) {
621	  const server = await loadServer(job);
622	  if (SANDBOX) {
623	    if (unsuspend) {
624	      await db.server.update({ where: { id: server.id }, data: { status: "RUNNING", suspendedNote: null, suspendReason: null } });
625	    } else {
626	      await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
627	    }
628	    return;
629	  }
630	  const { conn, row: nodeRow } = await nodeFor(server);
631	  if (unsuspend) {
632	    // The dedicated IP was returned to the pool while suspended — re-allocate one
633	    // and reconfigure the public network before starting the VM back up.
634	    if (server.vmid) {
635	      const { getSettingBool: _sb } = await import("../lib/settings");
636	      const wantDedicated = server.wantsDedicatedIp || (await _sb("dedicated_ip_default", true));
637	      const alreadyHas = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
638	      let reconfigured = alreadyHas ? true : false;
639	      if (wantDedicated && ovhConfigured() && !alreadyHas) {
640	        try {
641	          const d = await allocateDedicatedIp(server.id, server.vmid);
642	          if (d) {
643	            await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
644	              net0: `virtio=${d.virtualMac},bridge=vmbr0`,
645	              ipconfig0: `ip=${d.address}/32,gw=${d.gateway}`,
646	            });
647	            await db.server.update({ where: { id: server.id }, data: { ipAddress: d.address, sshPort: null } });
648	            reconfigured = true;
649	          }
650	        } catch (e) {
651	          console.error("[worker] re-allocate dedicated IP on unsuspend failed; falling back to NAT", e);
652	        }
653	      }
654	      // If we couldn't (or didn't) give it a dedicated IP, its net0 still points at
655	      // the Virtual MAC + failover IP that suspend released back to the pool — that
656	      // IP may now belong to another server. Reconfigure onto shared NAT so it boots
657	      // with a valid, non-conflicting network instead of a dead public config.
658	      if (!reconfigured) {
659	        try {
660	          const ip = server.ipAddress ?? (await allocateIp(server.nodeId, server.id));
661	          const sshPort = server.sshPort ?? (await allocateSshPort(server.nodeId, server.id));
662	          await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
663	            net0: `virtio,bridge=${nodeRow?.bridge ?? "vmbr1"}`,
664	            ipconfig0: `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`,
665	          });
666	          await db.server.update({ where: { id: server.id }, data: { ipAddress: ip, sshPort } });
667	        } catch (e) {
668	          console.error("[worker] NAT fallback on unsuspend failed", e);
669	        }
670	      }
671	    }
672	    await db.server.update({ where: { id: server.id }, data: { status: "STOPPED", suspendedNote: null, suspendReason: null } });
673	    // Not fatal to the unsuspend itself (the customer is paid up and the VM must
674	    // come back), but never silent: an unproved sync is logged with its reason.
675	    if (!SANDBOX) await syncPortForwardsBestEffort(`unsuspend ${server.hostname}`);
676	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
677	    await conn.waitForTask(upid);
678	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
679	  } else {
680	    try {
681	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
682	      await conn.waitForTask(upid);
683	    } catch { /* may already be stopped */ }
684	    await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
685	    if (!SANDBOX) await syncPortForwardsBestEffort(`suspend ${server.hostname}`);
686	    // Return the dedicated IP to the pool while the server is suspended, so it
687	    // can be handed to a paying server. Re-allocated on unsuspend.
688	    if (ovhConfigured()) {
689	      try {
690	        const had = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
691	        if (had) {
692	          await releaseDedicatedIp(server.id);
693	          // MUST also clear the address off the server: `Server.ipAddress` is UNIQUE,
694	          // so leaving the released IP here makes the next server that claims it fail
695	          // with P2002 — that server then silently lands on NAT while its OVH Virtual
696	          // MAC stays allocated and billable. (NAT servers keep their private IP.)
697	          await db.server.update({
698	            where: { id: server.id },
699	            data: { ipAddress: null, ipv6: null },
700	          });
701	        }
702	      } catch (e) {
703	        console.error("[worker] release dedicated IP on suspend failed", e);
704	      }
705	    }
706	  }
707	}
