717	async function resize(job: Job) {
718	  const server = await loadServer(job);
719	  const payload = (job.payload ?? {}) as { planId?: string };
720	  const newPlan = await db.plan.findUnique({ where: { id: payload.planId ?? "" } });
721	  if (!newPlan) throw new Error("resize: target plan not found");
722	  if (newPlan.diskGB < server.plan.diskGB) throw new Error("resize: disk can only grow");
723	
724	  // Any separately-purchased extra disk is ADDITIVE to whichever plan the server
725	  // sits on, so it survives the plan change untouched — `Server.extraDiskGB` is
726	  // never written here. Sizes below are therefore always the EFFECTIVE size
727	  // (new plan + extra); using the bare plan size would ask Proxmox to SHRINK the
728	  // disk of any server carrying extra storage, and the resize would hard-fail.
729	  const newTotalDiskGB = effectiveDiskGB(newPlan.diskGB, server.extraDiskGB);
730	  const currentTotalDiskGB = effectiveDiskGB(server.plan.diskGB, server.extraDiskGB);
731	  const diskLine =
732	    server.extraDiskGB > 0
