774	async function snapshotOp(job: Job, op: "create" | "delete" | "rollback") {
775	  const server = await loadServer(job);
776	  const payload = (job.payload ?? {}) as { name?: string };
777	  const name = (payload.name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
778	  if (!name) throw new Error("snapshot: invalid name");
779	  if (SANDBOX) {
780	    await notify(
781	      server.userId,
782	      `Snapshot ${op} (sandbox): ${name}`,
783	      `Sandbox snapshot ${op} completed (no real VM was touched).`,
784	      `/dashboard/servers/${server.id}`
785	    );
786	    return;
787	  }
788	  const { conn } = await nodeFor(server);
789	  let upid: string;
790	  if (op === "create") {
791	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot`, { snapname: name });
792	  } else if (op === "delete") {
793	    upid = await conn.del(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}`);
794	  } else {
795	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}/rollback`, {});
796	  }
797	  await conn.waitForTask(upid, 600_000);
