799	    // rollback leaves the VM stopped; bring it back if the server should be running
800	    const current = await db.server.findUnique({ where: { id: server.id } });
801	    if (current?.status === "RUNNING") {
802	      try {
803	        const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
804	        await conn.waitForTask(startUpid);
805	      } catch { /* may already be running */ }
806	    }
807	  }
808	}
