886	/**
887	 * Create one backup and PROVE it exists before saying so.
888	 *
889	 * INCIDENT H4 (2026-07-26 rehearsal): this handler gated only the vzdump task's
890	 * exit status — it never checked that an archive was written, had no failure
891	 * notification, and `Server.lastAutoBackup` was stamped by the SWEEP at enqueue
892	 * time. A customer could read "Last automatic backup: today" every night for a
893	 * month with nothing in storage, and find out at restore time.
894	 *
895	 * Now: snapshot the archive list before the run, re-read it after, and require a
896	 * volid that was not there and is not empty (`freshBackupProof`). Only that
897	 * writes `lastAutoBackup`. A failure notifies the customer with the reason and a
898	 * command, rather than leaving a stale-but-cheerful timestamp behind.
899	 */
900	async function backupCreate(job: Job) {
901	  const server = await loadServer(job);
902	  if (SANDBOX) {
903	    await sandboxAnimateJob(job.id, [
904	      { pct: 5, step: "Starting" },
905	      { pct: 25, step: "Creating archive… 25%" },
906	      { pct: 55, step: "Creating archive… 55%" },
907	      { pct: 80, step: "Creating archive… 80%" },
908	      { pct: 95, step: "Finalizing" },
909	      { pct: 100, step: "Backup complete" },
910	    ]);
911	    // Deliberately NOT stamping lastAutoBackup here: no archive exists, and the
912	    // column means "a backup was observed in storage".
913	    await notify(
914	      server.userId,
915	      `Backup simulated (sandbox) for ${server.hostname}`,
916	      "Sandbox only — no VM was contacted and no archive was written. This is not a restore point.",
917	      `/dashboard/servers/${server.id}`
918	    );
919	    return;
920	  }
921	  if (server.vmid == null) {
922	    throw new Error("backup: this server has no VMID yet, so there is nothing to back up.");
923	  }
924	  const vmid = server.vmid;
925	
926	  try {
927	    await reportJobProgress(job.id, 2, "Starting");
928	    const { conn } = await nodeFor(server);
929	
930	    // Snapshot what already exists. Membership of this set — not a timestamp
931	    // comparison — is what makes "a new archive appeared" unarguable: ctime comes
932	    // off the hypervisor and our window would come off the worker's clock.
933	    const before = await listBackupsOn(conn, vmid);
934	
935	    const upid = await conn.post(`/nodes/${conn.node}/vzdump`, {
936	      vmid,
937	      storage: "backup",
938	      mode: "snapshot",
939	      compress: "zstd",
940	    });
941	    await waitForTaskProgress(
942	      conn,
943	      upid,
944	      (progress, step) => reportJobProgress(job.id, progress, step),
945	      { timeoutMs: 3_600_000, phase: "backup" }
946	    );
947	
948	    await reportJobProgress(job.id, 96, "Verifying archive");
949	    const after = await listBackupsOn(conn, vmid);
950	    const proof = freshBackupProof({ vmid, before, after });
951	    if (!proof.proven) throw new Error(`backup not verified — ${proof.reason}`);
952	
953	    await reportJobProgress(job.id, 100, "Backup complete");
954	
955	    // Retention: keep only the latest few backups for this server; prune the rest.
956	    try {
957	      const pruned = await pruneBackups(conn, vmid, CUSTOMER_BACKUP_KEEP);
958	      if (pruned > 0) console.log(`[backup] pruned ${pruned} old backup(s) for vmid ${vmid} (keep ${CUSTOMER_BACKUP_KEEP})`);
959	    } catch (e) {
960	      console.error(`[backup] prune failed for vmid ${vmid}`, e);
961	    }
962	
963	    // The ONLY writer of lastAutoBackup, and only on proof.
964	    await db.server.update({ where: { id: server.id }, data: { lastAutoBackup: new Date() } });
965	
966	    await notify(
967	      server.userId,
968	      `Backup completed for ${server.hostname}`,
969	      `Verified present in backup storage: ${proof.volid} (${humanBytes(proof.sizeBytes)}).`,
970	      `/dashboard/servers/${server.id}`
971	    );
972	  } catch (e: any) {
973	    // Tell the customer it broke. Only on the final attempt, so the worker's
974	    // three retries do not produce three notifications for one bad night.
975	    if (job.attempts >= MAX_ATTEMPTS) {
976	      await notify(
977	        server.userId,
978	        `Backup FAILED for ${server.hostname}`,
979	        `${String(e?.message ?? e).slice(0, 400)} — this server has no new restore point. ` +
980	          `Your last verified backup (if any) is shown under Backups.`,
981	        `/dashboard/servers/${server.id}`
982	      );
983	    }
984	    throw e;
985	  }
986	}
