1029	/**
1030	 * Refund a per-server disk expansion that was paid for but never delivered.
1031	 *
1032	 * The DISK_EXPAND handler advances `Server.extraDiskGB` only AFTER the disk has
1033	 * really grown, so that field is the ground truth for "did the customer get what
1034	 * they paid for". We refund only when it never reached the job's target — which
1035	 * also keeps this safe against the partial-success case (disk grown, filesystem
1036	 * left for the customer to grow by hand): that path completes successfully, sets
1037	 * extraDiskGB, and is therefore never refunded.
1038	 *
1039	 * Idempotent per job via the reconcile audit marker.
1040	 */
1041	async function reconcileFailedDiskExpand(job: Job) {
1042	  const p = (job.payload ?? {}) as { prorateCents?: number; addGB?: number; targetExtraDiskGB?: number };
1043	  const cents = p.prorateCents ?? 0;
1044	  if (cents <= 0 || !job.serverId) return;
1045	
1046	  const already = await db.auditLog.findFirst({
1047	    where: { action: "server.disk_expand.reconcile", detail: { contains: `job=${job.id}` } },
1048	  });
1049	  if (already) return;
1050	
1051	  const server = await db.server.findUnique({
1052	    where: { id: job.serverId },
1053	    select: { userId: true, hostname: true, extraDiskGB: true },
1054	  });
1055	  if (!server) return;
1056	
1057	  // The expansion actually landed (or a later one superseded it) — the customer
1058	  // has the storage, so the charge stands. Nothing to unwind.
1059	  const target = Number(p.targetExtraDiskGB ?? 0);
1060	  if (target > 0 && server.extraDiskGB >= target) return;
1061	
1062	  try {
1063	    await db.$transaction([
1064	      db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
1065	      db.walletTransaction.create({
1066	        data: {
1067	          userId: server.userId,
1068	          amountCents: cents,
1069	          description: `Refund: failed storage expansion (+${p.addGB ?? "?"} GB) — ${server.hostname}`,
1070	        },
1071	      }),
1072	      db.notification.create({
1073	        data: {
1074	          userId: server.userId,
1075	          title: `Storage expansion failed on ${server.hostname} — refunded`,
1076	          body: `We couldn't add the storage, so $${(cents / 100).toFixed(2)} has been credited back to your wallet. Your server and its data are untouched.`,
1077	          href: `/dashboard/servers/${job.serverId}`,
1078	        },
1079	      }),
1080	    ]);
1081	    await db.auditLog.create({
1082	      data: {
1083	        userId: server.userId,
1084	        action: "server.disk_expand.reconcile",
1085	        detail: `job=${job.id} addGB=${p.addGB} cents=${cents}`,
1086	      },
1087	    });
1088	  } catch (e: any) {
1089	    await db.auditLog
1090	      .create({
1091	        data: {
1092	          userId: server.userId,
1093	          action: "server.disk_expand.reconcile.uncharged",
1094	          detail: `job=${job.id} cents=${cents} :: ${e?.message ?? e}`,
1095	        },
1096	      })
1097	      .catch(() => {});
1098	  }
1099	}
