1101	/**
1102	 * Reverse a money side-effect that a job committed up-front but never delivered.
1103	 * Server actions charge/credit the wallet before enqueuing the worker job (so the
1104	 * UI reflects the change immediately); if the job then fails terminally the money
1105	 * must be unwound or the customer is charged for a resize that never happened
1106	 * (up) or keeps a downgrade credit for hardware they still have (down).
1107	 * Idempotent per job: guarded by the RECONCILED audit marker so a re-run can't
1108	 * double-reverse.
1109	 */
1110	async function reconcileFailedJob(job: Job) {
1111	  if (job.type === "DISK_EXPAND") return reconcileFailedDiskExpand(job);
1112	  if (job.type !== "RESIZE") return;
1113	  const p = (job.payload ?? {}) as { prorateCents?: number; direction?: "up" | "down" };
1114	  const cents = p.prorateCents ?? 0;
1115	  if (cents <= 0 || !job.serverId) return;
1116	
1117	  // Idempotency: skip if we already reversed this exact job.
1118	  const already = await db.auditLog.findFirst({
1119	    where: { action: "server.resize.reconcile", detail: { contains: `job=${job.id}` } },
1120	  });
1121	  if (already) return;
1122	
1123	  const server = await db.server.findUnique({ where: { id: job.serverId }, select: { userId: true, hostname: true } });
1124	  if (!server) return;
1125	
1126	  try {
1127	    if (p.direction === "up") {
1128	      // Upgrade charge never delivered → refund the prorated charge.
1129	      await db.$transaction([
1130	        db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
1131	        db.walletTransaction.create({
1132	          data: { userId: server.userId, amountCents: cents, description: `Refund: failed upgrade — ${server.hostname}` },
1133	        }),
1134	      ]);
1135	    } else if (p.direction === "down") {
1136	      // Downgrade credit was given but hardware unchanged → claw the credit back.
1137	      // Guarded so it can never drive the balance negative; if the customer already
1138	      // spent it, we log and leave it (best-effort — they keep a small windfall).
1139	      await db.$transaction(async (tx) => {

1140	        await debitWallet(tx, server.userId, cents);
1141	        await tx.walletTransaction.create({
1142	          data: { userId: server.userId, amountCents: -cents, description: `Reversed downgrade credit (resize failed) — ${server.hostname}` },
1143	        });
1144	      });
1145	    }
1146	    await db.auditLog.create({
1147	      data: { userId: server.userId, action: "server.resize.reconcile", detail: `job=${job.id} dir=${p.direction} cents=${cents}` },
1148	    });
1149	  } catch (e: any) {
1150	    // InsufficientBalanceError on a down-reversal is expected/acceptable; record it.
1151	    await db.auditLog.create({
1152	      data: { userId: server.userId, action: "server.resize.reconcile.uncharged", detail: `job=${job.id} dir=${p.direction} cents=${cents} :: ${e?.message ?? e}` },
1153	    }).catch(() => {});
1154	  }
1155	}
