1157	async function runJob(job: Job) {
1158	  // The job is already atomically claimed (status RUNNING, attempts incremented)
1159	  // by the loop's compare-and-swap before we get here — see the CAS in main().
1160	  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
1161	  try {
1162	    await handlers[job.type](job);
1163	    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
1164	    console.log(`[worker] job ${job.id} DONE`);
1165	  } catch (e: any) {
1166	    let error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`;
1167	    // Defense in depth: a child process (e.g. `sshpass -p <rootPassword> …`) can
1168	    // leak the server's root password into the thrown message. Redact it before
1169	    // it is persisted to Job.error. Redact BEFORE slicing so a truncation can't
1170	    // sever the match. Best-effort — never let redaction lookup fail the job path.
1171	    if (job.serverId) {
1172	      try {
1173	        const s = await db.server.findUnique({
1174	          where: { id: job.serverId },
1175	          select: { rootPassword: true, rootPasswordEnc: true },
1176	        });
1177	        const pw = s ? serverRootPassword(s) : null;
1178	        if (pw) error = error.split(pw).join("***");
1179	      } catch {
1180	        /* best-effort redaction */
1181	      }
1182	    }
1183	    error = error.slice(0, 2000);
1184	    console.error(`[worker] job ${job.id} FAILED: ${error}`);
1185	    const current = await db.job.findUnique({ where: { id: job.id } });
1186	    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
1187	    await db.job.update({
1188	      where: { id: job.id },
1189	      data: { status: retriable ? "QUEUED" : "FAILED", error },
1190	    });
1191	    if (!retriable) {
1192	      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
1193	      // Persist terminal job failures to ErrorLog (deduped by fingerprint) so the
1194	      // admin Error Logs view surfaces what broke on the customer side, not just
1195	      // the transient Job.error. logError is already non-throwing; guard anyway.
1196	      await logError(`job.${String(job.type).toLowerCase()}`, new Error(error), {
1197	        source: "job",
1198	        jobId: job.id,
1199	        serverId: job.serverId ?? undefined,
1200	      }).catch(() => {});
1201	      if (job.serverId) {
1202	        const stillExists = await db.server.findUnique({ where: { id: job.serverId } });
1203	        if (stillExists) {
1204	          // Only jobs that actually change the VM's run/disk state should strand the
1205	          // server in ERROR. Side operations — backup, snapshot-create, the control-
1206	          // panel db/website/app/cron/service ops, SSL, migrate copy, game update —
1207	          // never touch the VM's run state; their failures surface via the executor's
1208	          // own notification and must NOT flip the whole server to ERROR (a failed
1209	          // backup was wrongly making the server look like it had shut down).
1210	          if (VM_STATE_FAILURE_JOBS.has(job.type)) {
1211	            await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
1212	          }
1213	          // A terminally-failed PROVISION must not leak its allocated dedicated IP,
1214	          // nor free a NAT IP its surviving VM still holds — see cleanupFailedProvision.
1215	          if (job.type === "PROVISION") {
1216	            await cleanupFailedProvision(job.serverId);
1217	          }
1218	        }
