/// Tracking event types for the Phase 2 pipeline. Append-only by design.
/// SENT/DELIVERED/FAILED are written by the send worker; OPEN/CLICK by the
/// tracking routes; BOUNCE/COMPLAINT/UNSUBSCRIBE by the feedback + unsubscribe
/// paths. Additive to the Phase 1 set — never reorder or remove a value.
enum EmailEventType {
  OPEN
  CLICK
  BOUNCE
  COMPLAINT
  UNSUBSCRIBE
  SENT
  DELIVERED
  FAILED
}

  spfVerified           Boolean  @default(false)
  dkimVerified          Boolean  @default(false)
  dmarcVerified         Boolean  @default(false)
  // Phase 2 sending controls.
  // warmupStartedAt anchors the per-inbox warmup ramp (day 1 = a handful/day,
  // growing to the ceiling). null = no warmup started (treated as "still on day 1").
  warmupStartedAt       DateTime?
  // Optional per-brand override of the platform daily cap; null = use the global
  // `coldemail_daily_cap` setting. The cap INCLUDES warmup traffic.
  dailySendCap          Int?
  // Complaint-rate circuit breaker: when tripped the send worker refuses this
  // brand until an operator clears it. `pausedReason` records why.
  sendingPaused         Boolean  @default(false)
  pausedReason          String   @default("")
  createdAt             DateTime @default(now())

  lists        EmailList[]
  suppressions Suppression[]
  campaigns    ColdCampaign[]

  @@index([createdAt])
}

model ColdSend {
  id         String         @id @default(cuid())
  campaignId String
  contactId  String
  // Which sequence step this send is for. Nullable + SetNull so deleting a step
  // never orphans-cascade a historical send; a scheduled (not-yet-sent) send for a
  // removed step is simply left with no step and skipped.
  stepId     String?
  status     ColdSendStatus @default(QUEUED)
  // Phase 2 scheduling + delivery bookkeeping.
  scheduledFor DateTime?
  sentAt       DateTime?
  messageId    String?
  error        String?
  // Stateless HMAC token embedded in the open pixel + click links for this send.
  trackingToken String?  @unique
  createdAt  DateTime       @default(now())

  campaign ColdCampaign  @relation(fields: [campaignId], references: [id], onDelete: Cascade)
  contact  Contact       @relation(fields: [contactId], references: [id], onDelete: Cascade)
  step     SequenceStep? @relation(fields: [stepId], references: [id], onDelete: SetNull)
  events   EmailEvent[]

  // One send per (campaign, contact, step) — makes the scheduler idempotent: it
  // can re-run without ever double-queuing the same message.
  @@unique([campaignId, contactId, stepId])
  @@index([campaignId])
  @@index([contactId])
  @@index([status])
  @@index([scheduledFor])
  @@index([sentAt])
}

model EmailEvent {
  id        String         @id @default(cuid())
  sendId    String
  type      EmailEventType
  // Optional context — e.g. the clicked URL for a CLICK, or the failure reason for
  // a FAILED. Free text, never trusted for control flow.
  meta      String         @default("")
  createdAt DateTime       @default(now())

  send ColdSend @relation(fields: [sendId], references: [id], onDelete: Cascade)

  @@index([sendId])
  @@index([type])
  @@index([createdAt])
}

// ---------------------------------------------------------------------------
// Open / click tracking tokens (stateless, HMAC-signed, same key as unsubscribe)
// ---------------------------------------------------------------------------

const OPEN_TOKEN_VERSION = "o1";
const CLICK_TOKEN_VERSION = "c1";

/**
 * A tamper-proof open-pixel token for one send. Shape:
 * `o1.<base64url(sendId)>.<hmac>`. The pixel route verifies the signature then
 * writes an OPEN EmailEvent — no DB lookup by token is required, but the token is
 * also stored on the ColdSend row for auditing.
 */
export function openTrackingToken(sendId: string): string {
  const body = Buffer.from(sendId, "utf8").toString("base64url");
  const payload = `${OPEN_TOKEN_VERSION}.${body}`;
  return `${payload}.${sign(payload)}`;
}

/** Verify an open token; returns the sendId or null. Constant-time compare. */
export function verifyOpenToken(token: string | null | undefined): string | null {
  if (!token) return null;
  const parts = token.split(".");
  if (parts.length !== 3) return null;
  const [version, body, mac] = parts;
  if (version !== OPEN_TOKEN_VERSION) return null;
  const a = Buffer.from(mac);
  const b = Buffer.from(sign(`${version}.${body}`));
  if (a.length !== b.length || !timingSafeEqual(a, b)) return null;
  try {
    const sendId = Buffer.from(body, "base64url").toString("utf8");
    return sendId || null;
  } catch {
    return null;
  }
}

/**
 * A tamper-proof click-redirect token carrying the destination URL. Shape:
 * `c1.<base64url(sendId)>.<base64url(url)>.<hmac>`. Signing the URL is what stops
 * the click route becoming an open redirect: an attacker cannot swap in their own
 * destination without invalidating the HMAC.
 */
export function clickTrackingToken(sendId: string, url: string): string {
  const b1 = Buffer.from(sendId, "utf8").toString("base64url");
  const b2 = Buffer.from(url, "utf8").toString("base64url");
  const payload = `${CLICK_TOKEN_VERSION}.${b1}.${b2}`;
  return `${payload}.${sign(payload)}`;
}

export type ClickClaims = { sendId: string; url: string };

/** Verify a click token; returns { sendId, url } or null. Constant-time compare. */
export function verifyClickToken(token: string | null | undefined): ClickClaims | null {
  if (!token) return null;
  const parts = token.split(".");
  if (parts.length !== 4) return null;
  const [version, b1, b2, mac] = parts;
  if (version !== CLICK_TOKEN_VERSION) return null;
  const a = Buffer.from(mac);
  const b = Buffer.from(sign(`${version}.${b1}.${b2}`));
  if (a.length !== b.length || !timingSafeEqual(a, b)) return null;
  try {
    const sendId = Buffer.from(b1, "base64url").toString("utf8");
    const url = Buffer.from(b2, "base64url").toString("utf8");
    // Only ever redirect to absolute http(s) URLs — defence in depth on top of the
    // signature so a signed-but-malformed target can never drive the redirect.
    if (!sendId || !/^https?:\/\//i.test(url)) return null;
    return { sendId, url };
  } catch {
    return null;
  }
}

