export function dailyCapOk(sentToday: number, cap: number = DEFAULT_DAILY_CAP): boolean {
  const ceiling = cap > 0 ? cap : DEFAULT_DAILY_CAP;
  return sentToday < ceiling;
}

/** Per-inbox warmup ramp: day 1 = 5, +5/day, capped at the safe ceiling. */
export const WARMUP_STEP = 5;

/**
 * Whole days elapsed since `startedAt` (0 on the first day). `null` startedAt is
 * treated as day 0 — a brand with no recorded warmup start is on its first day,
 * never uncapped. Negative results (clock skew, future start) clamp to 0.
 */
export function warmupDayIndex(
  startedAt: Date | string | null | undefined,
  now: Date | number = Date.now(),
): number {
  if (!startedAt) return 0;
  const start = startedAt instanceof Date ? startedAt.getTime() : new Date(startedAt).getTime();
  if (!Number.isFinite(start)) return 0;
  const nowMs = now instanceof Date ? now.getTime() : now;
  const days = Math.floor((nowMs - start) / 86_400_000);
  return days > 0 ? days : 0;
}

/**
 * The daily cap for an inbox on a given warmup day. `dayIndex` is 0-based (day 1
 * of warmup = index 0 → 5). Grows by WARMUP_STEP per day and never exceeds the
 * warmup-safe ceiling — the ceiling INCLUDES warmup traffic, per the deliverability
 * plan. A non-positive ceiling falls back to the safe default, never "unlimited".
 */
export function warmupDailyCap(dayIndex: number, ceiling: number = DEFAULT_DAILY_CAP): number {
  const cap = ceiling > 0 ? ceiling : DEFAULT_DAILY_CAP;
  const day = Number.isFinite(dayIndex) ? Math.max(0, Math.floor(dayIndex)) : 0;
  const ramped = WARMUP_STEP * (day + 1);
  return Math.min(cap, ramped);
}

/**
 * The effective per-inbox cap for a brand right now: the warmup ramp when warmup
 * is enabled, otherwise the flat ceiling. `ceiling` is the brand override or the
 * platform default.
 */
export function effectiveDailyCap(opts: {
  warmupStartedAt?: Date | string | null;
  ceiling?: number;
  warmupEnabled?: boolean;
  now?: Date | number;
}): number {
  const ceiling = opts.ceiling && opts.ceiling > 0 ? opts.ceiling : DEFAULT_DAILY_CAP;
  if (opts.warmupEnabled === false) return ceiling;
  return warmupDailyCap(warmupDayIndex(opts.warmupStartedAt, opts.now ?? Date.now()), ceiling);
}

