/** Convenience: true when the brand has no outstanding compliance requirements. */
export function brandIsCompliant(brand: BrandLike): boolean {
  return requireBrandCompliance(brand).length === 0;
}

// ---------------------------------------------------------------------------
// Reputation isolation — protected sending domains
// ---------------------------------------------------------------------------

/**
 * Domains the cold-email engine must NEVER send from, no matter how a brand is
 * configured. These carry the platform's transactional + mailbox reputation, so a
 * cold campaign leaking onto them would put customer mail (receipts, password
 * resets, business mailboxes) at deliverability risk. Always includes the mail
 * host; callers merge in the app host + any operator-configured domains.
 */
export const ALWAYS_PROTECTED_DOMAINS: readonly string[] = ["nxeon.cloud", "mail.nxeon.cloud"];

/** Lower-case, strip a leading protocol/@, and drop any path/port from a domain. */
export function normalizeDomain(value: string | null | undefined): string {
  let d = (value ?? "").trim().toLowerCase();
  if (!d) return "";
  const at = d.lastIndexOf("@");
  if (at !== -1) d = d.slice(at + 1);
  d = d.replace(/^https?:\/\//, "");
  d = d.split("/")[0].split(":")[0];
  return d.trim();
}

/**
 * Build the full protected-domain set from the operator setting plus the
 * always-protected base and the app host. Deduped, normalised, no empties.
 */
export function protectedDomainSet(configured: string | null | undefined, appHost?: string | null): Set<string> {
  const out = new Set<string>();
  for (const d of ALWAYS_PROTECTED_DOMAINS) out.add(normalizeDomain(d));
  const host = normalizeDomain(appHost);
  if (host) out.add(host);
  for (const tok of (configured ?? "").split(/[\s,;]+/)) {
    const d = normalizeDomain(tok);
    if (d) out.add(d);
  }
  out.delete("");
  return out;
}

/**
 * Is `domain` protected? Matches the exact domain AND any subdomain of a protected
 * apex (so `bulk.nxeon.cloud` is blocked when `nxeon.cloud` is protected).
 */
export function isProtectedDomain(domain: string | null | undefined, protectedSet: Set<string> | string[]): boolean {
  const d = normalizeDomain(domain);
  if (!d) return true; // no sending domain at all → refuse, never fail open
  const set = protectedSet instanceof Set ? protectedSet : new Set(protectedSet.map(normalizeDomain));
  if (set.has(d)) return true;
  for (const p of set) {
    if (p && d.endsWith(`.${p}`)) return true;
  }
  return false;
}

export type SendEligibility = {
  eligible: boolean;
  reasons: string[];
  checks: { key: string; label: string; ok: boolean }[];
};

/**
 * The full send-eligibility verdict for a brand: CAN-SPAM/DNS compliance
 * (requireBrandCompliance) PLUS reputation isolation (the From domain must not be
 * protected) PLUS the circuit-breaker pause flag. Returns a red/green checklist
 * for the UI and a machine-usable `eligible`. This is the single gate the worker
 * and the Launch action both consult, so they can never disagree.
 */
export function evaluateSendEligibility(
  brand: BrandLike & { fromEmail?: string | null; sendingDomain?: string | null; sendingPaused?: boolean },
  protectedSet: Set<string> | string[],
): SendEligibility {
  const missing = requireBrandCompliance(brand);
  const complianceOk = missing.length === 0;

  const fromDomain = normalizeDomain(brand.sendingDomain) || normalizeDomain(brand.fromEmail);
  const notProtected = !isProtectedDomain(fromDomain, protectedSet);
  const hasFromDomain = !!fromDomain;
  const notPaused = !brand.sendingPaused;

  const checks = [
    { key: "address", label: "Physical postal address", ok: !!(brand.physicalPostalAddress ?? "").trim() },
    {
      key: "dns",
      label: "SPF + DKIM + DMARC verified",
      ok: !!(brand.spfVerified && brand.dkimVerified && brand.dmarcVerified),
    },
    { key: "dedicatedDomain", label: "Dedicated sending domain set", ok: hasFromDomain },
    { key: "notProtected", label: "Not a protected/platform domain", ok: hasFromDomain && notProtected },
    { key: "notPaused", label: "Not paused by the circuit breaker", ok: notPaused },
  ];

  const reasons: string[] = [];
  for (const m of missing) reasons.push(m.label);
  if (!hasFromDomain) reasons.push("No dedicated sending domain configured");
  else if (!notProtected) {
    reasons.push(
      `Sending domain "${fromDomain}" is a protected platform domain — cold email must use a dedicated domain`,
    );
  }
  if (!notPaused) reasons.push(`Sending is paused${brand.pausedReason ? `: ${brand.pausedReason}` : ""}`);

  return {
    eligible: complianceOk && hasFromDomain && notProtected && notPaused,
    reasons,
    checks,
  };
}

brand: BrandLike & {
  fromEmail?: string | null;
  sendingDomain?: string | null;
  sendingPaused?: boolean;
  pausedReason?: string | null;
},
protectedSet: Set<string> | string[],

