input.content:
// Cold Email Engine — bounce / complaint handling + complaint circuit breaker.
//
// This is the "use side" of deliverability protection: a bounce or spam complaint
// must (a) suppress the address so we never mail it again, and (b) feed the
// complaint-rate circuit breaker that pauses a whole brand before its reputation —
// and every other brand sharing the platform — is damaged.
//
// No live IMAP/FBL polling this phase. The seam is here: a server action or the
// inbound webhook stub (app/api/coldemail/feedback) calls `recordFeedback`, which
// is the single choke point. Wire SES SNS / Mailcow FBL into that route later.

import { db } from "@/lib/db";
import { normalizeEmail, normalizeDomain } from "@/lib/coldemail/compliance";
import { getSetting } from "@/lib/settings";
import { logEvent } from "@/lib/log";

export type FeedbackKind = "BOUNCE" | "COMPLAINT";

/**
 * Look back this far when computing a brand's complaint rate. A rolling window
 * keeps one bad historical week from pinning the brand paused forever once hygiene
 * recovers.
 */
const COMPLAINT_WINDOW_DAYS = 30;

/** Don't trip the breaker until there's enough volume for a rate to be meaningful. */
const COMPLAINT_MIN_SENDS = 50;

/**
 * Record a bounce or complaint for an address: write a GLOBAL Suppression (so no
 * brand ever re-contacts it), attach the matching EmailEvent to the most recent
 * send if we can find one, and — for complaints — run the circuit breaker.
 *
 * Idempotent on the suppression (check-then-insert on the GLOBAL row). Never
 * throws to the caller — feedback ingestion must not fail a webhook.
 */
export async function recordFeedback(
  rawEmail: string,
  kind: FeedbackKind,
  opts: { brandId?: string | null; note?: string } = {},
): Promise<{ ok: boolean; suppressed: boolean; brandPaused?: boolean }> {
  const email = normalizeEmail(rawEmail);
  if (!email || !email.includes("@")) return { ok: false, suppressed: false };

  try {
    // 1) GLOBAL suppression (idempotent). Bounces + complaints are always global —
    //    a bad address stays bad for every brand.
    const existing = await db.suppression.findFirst({ where: { email, scope: "GLOBAL" }, select: { id: true } });
    if (!existing) {
      await db.suppression.create({ data: { email, scope: "GLOBAL", reason: kind } });
    }

    // 2) Attach an event to the latest send to this address, if one exists, so the
    //    campaign stats reflect the bounce/complaint.
    const contact = await db.contact.findUnique({ where: { email }, select: { id: true } });
    let brandId = opts.brandId ?? null;
    if (contact) {
      const lastSend = await db.coldSend.findFirst({
        where: { contactId: contact.id },
        orderBy: { createdAt: "desc" },
        select: { id: true, campaign: { select: { brandId: true } } },
      });
      if (lastSend) {
        await db.emailEvent.create({
          data: { sendId: lastSend.id, type: kind, meta: (opts.note ?? "").slice(0, 300) },
        });
        brandId = brandId ?? lastSend.campaign.brandId;
      }
    }

    // 3) Complaint circuit breaker.
    let brandPaused = false;
    if (kind === "COMPLAINT" && brandId) {
      brandPaused = await maybeTripCircuitBreaker(brandId);
    }

    return { ok: true, suppressed: true, brandPaused };
  } catch (err) {
    await logEvent("error", "coldemail.feedback.record", { message: String(err), kind, email });
    return { ok: false, suppressed: false };
  }
}

/** Sends + complaints for a brand over the rolling window. */
export async function complaintStats(brandId: string): Promise<{ sends: number; complaints: number; rate: number }> {
  const since = new Date(Date.now() - COMPLAINT_WINDOW_DAYS * 86_400_000);
  const sends = await db.coldSend.count({
    where: { campaign: { brandId }, sentAt: { gte: since } },
  });
  const complaints = await db.emailEvent.count({
    where: { type: "COMPLAINT", createdAt: { gte: since }, send: { campaign: { brandId } } },
  });
  const rate = sends > 0 ? complaints / sends : 0;
  return { sends, complaints, rate };
}

/**
 * Pause the brand if its complaint rate is over the configured threshold and it
 * has enough volume to matter. Returns whether it ended up paused. This is what
 * stops one bad campaign from taking down all three brands' shared reputation.
 */
export async function maybeTripCircuitBreaker(brandId: string): Promise<boolean> {
  const threshold = Number(await getSetting("coldemail_complaint_threshold")) || 0.003;
  const { sends, complaints, rate } = await complaintStats(brandId);
  if (sends < COMPLAINT_MIN_SENDS) return false;
  if (rate < threshold) return false;

  const brand = await db.brand.findUnique({ where: { id: brandId }, select: { sendingPaused: true } });
  if (brand?.sendingPaused) return true; // already paused

  await db.brand.update({
    where: { id: brandId },
    data: {
      sendingPaused: true,
      pausedReason: `Complaint rate ${(rate * 100).toFixed(2)}% (${complaints}/${sends}) exceeded ${(threshold * 100).toFixed(2)}% — auto-paused`,
    },
  });
  await logEvent("warn", "coldemail.circuit_breaker.trip", { brandId, rate, complaints, sends, threshold });
  return true;
}

/** Manually clear a brand's circuit-breaker pause (operator action after cleanup). */
export async function clearCircuitBreaker(brandId: string): Promise<void> {
  await db.brand.update({ where: { id: brandId }, data: { sendingPaused: false, pausedReason: "" } });
}

/** Manual bulk suppression helper for a domain (e.g. a whole company complained). */
export async function suppressDomain(rawDomain: string, reason: FeedbackKind): Promise<boolean> {
  const domain = normalizeDomain(rawDomain);
  if (!domain || !domain.includes(".")) return false;
  const existing = await db.suppression.findFirst({ where: { domain, scope: "GLOBAL" }, select: { id: true } });
  if (!existing) await db.suppression.create({ data: { domain, scope: "GLOBAL", reason } });
  return true;
}

// Cold Email Engine — send-queue processor (Phase 2).
//
// Registered on the worker loop (worker/index.ts) and gated HARD behind the
// `cold_email_sending_enabled` master kill-switch: while that Setting is false
// this sweep returns immediately and NOTHING is scheduled, rendered, or sent.
//
// For each SENDING campaign it:
//   1. Re-checks brand send-eligibility (compliance + reputation isolation +
//      circuit-breaker pause). A blocked brand is skipped, never sent.
//   2. Expands the list → contacts → schedules a ColdSend per SequenceStep,
//      honouring delayDays (idempotent via the unique (campaign, contact, step)).
//   3. Sends due rows, enforcing at SEND TIME: suppression re-check, per-inbox
//      daily cap with the warmup ramp, and the send window — writing ColdSend
//      status (SENT/FAILED/SUPPRESSED) + an EmailEvent, throttled with jitter.
//
// Every count comes from the DB; the only external call is the SMTP send itself,
// which is unreachable in tests because the kill-switch keeps this inert.

import { db } from "../lib/db";
import { getSetting, getSettingBool, getSettingInt } from "../lib/settings";
import {
  isSuppressed,
  evaluateSendEligibility,
  protectedDomainSet,
  effectiveDailyCap,
  openTrackingToken,
  type SuppressionLike,
} from "../lib/coldemail/compliance";
import { buildMessage, getTransport, type SendIdentity, type MailTransport } from "../lib/coldemail/sender";
import { logEvent } from "../lib/log";

/** Upper bound on sends per sweep — keeps each worker tick light + jitter sane. */
const MAX_SENDS_PER_SWEEP = 50;
/** Throttle window (ms) between real sends — jittered to look human, not blasty. */
const THROTTLE_MIN_MS = 800;
const THROTTLE_MAX_MS = 2600;

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const jitter = () => THROTTLE_MIN_MS + Math.floor(Math.random() * (THROTTLE_MAX_MS - THROTTLE_MIN_MS));

function appHost(): string | null {
  try {
    return process.env.APP_URL ? new URL(process.env.APP_URL).host : null;
  } catch {
    return null;
  }
}

function startOfUtcDay(now = new Date()): Date {
  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
}

/** Current minute-of-day in a timezone (falls back to UTC on a bad tz). */
function minutesInTz(now: Date, tz: string): number {
  try {
    const parts = new Intl.DateTimeFormat("en-US", {
      timeZone: tz || "UTC",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false,
    }).formatToParts(now);
    const h = Number(parts.find((p) => p.type === "hour")?.value ?? "0") % 24;
    const m = Number(parts.find((p) => p.type === "minute")?.value ?? "0");
    return h * 60 + m;
  } catch {
    return now.getUTCHours() * 60 + now.getUTCMinutes();
  }
}

function withinSendWindow(
  c: { sendWindowStart: number | null; sendWindowEnd: number | null; timezone: string },
  now: Date,
): boolean {
  if (c.sendWindowStart == null || c.sendWindowEnd == null) return true;
  const cur = minutesInTz(now, c.timezone || "UTC");
  const s = c.sendWindowStart;
  const e = c.sendWindowEnd;
  return s <= e ? cur >= s && cur < e : cur >= s || cur < e; // handle wrap past midnight
}

type CampaignForSend = {
  id: string;
  brandId: string;
  listId: string;
  launchedAt: Date | null;
  sendWindowStart: number | null;
  sendWindowEnd: number | null;
  timezone: string;
};

/**
 * Ensure a ColdSend row exists for every (contact, step) in a campaign, with the
 * scheduledFor honouring cumulative step delays from the launch anchor. Idempotent
 * — the unique(campaignId, contactId, stepId) + skipDuplicates makes re-runs free.
 */
async function scheduleCampaignSends(campaign: CampaignForSend): Promise<void> {
  const steps = await db.sequenceStep.findMany({
    where: { campaignId: campaign.id },
    orderBy: { stepOrder: "asc" },
    select: { id: true, delayDays: true },
  });
  if (steps.length === 0) return;

  const base = campaign.launchedAt ?? new Date();
  // Cumulative offset (days) at each step.
  let cumulative = 0;
  const stepSchedule = steps.map((s) => {
    cumulative += Math.max(0, s.delayDays);
    return { stepId: s.id, scheduledFor: new Date(base.getTime() + cumulative * 86_400_000) };
  });

  const members = await db.emailListMember.findMany({
    where: { listId: campaign.listId },
    select: { contactId: true },
  });
  if (members.length === 0) return;

  const rows: { campaignId: string; contactId: string; stepId: string; scheduledFor: Date }[] = [];
  for (const m of members) {
    for (const s of stepSchedule) {
      rows.push({ campaignId: campaign.id, contactId: m.contactId, stepId: s.stepId, scheduledFor: s.scheduledFor });
    }
  }
  // createMany + skipDuplicates: never double-queues a message across sweeps.
  await db.coldSend.createMany({ data: rows, skipDuplicates: true });
}

/**
 * Process due sends for one eligible campaign. Returns the number actually sent so
 * the caller can respect the per-sweep budget across campaigns.
 */
async function processDueSends(
  campaign: CampaignForSend,
  identity: SendIdentity,
  ctx: {
    now: Date;
    transport: MailTransport;
    ceiling: number;
    warmupEnabled: boolean;
    footerDisclosure: string;
    budget: number;
  },
): Promise<number> {
  if (ctx.budget <= 0) return 0;
  if (!withinSendWindow(campaign, ctx.now)) return 0;

  // Per-inbox daily cap (warmup-aware). Counts REAL sends today for the brand.
  const brand = await db.brand.findUnique({
    where: { id: campaign.brandId },
    select: { warmupStartedAt: true, dailySendCap: true },
  });
  const cap = effectiveDailyCap({
    warmupStartedAt: brand?.warmupStartedAt ?? null,
    ceiling: brand?.dailySendCap ?? ctx.ceiling,
    warmupEnabled: ctx.warmupEnabled,
    now: ctx.now,
  });
  let sentToday = await db.coldSend.count({
    where: { campaign: { brandId: campaign.brandId }, sentAt: { gte: startOfUtcDay(ctx.now) } },
  });
  if (sentToday >= cap) return 0;

  // Suppression rows for this brand, loaded once (GLOBAL + this brand's BRAND tier).
  const suppressions: SuppressionLike[] = await db.suppression.findMany({
    where: { OR: [{ scope: "GLOBAL" }, { scope: "BRAND", brandId: campaign.brandId }] },
    select: { email: true, domain: true, scope: true, brandId: true },
  });

  const due = await db.coldSend.findMany({
    where: {
      campaignId: campaign.id,
      status: "QUEUED",
      stepId: { not: null },
      scheduledFor: { lte: ctx.now },
    },
    orderBy: { scheduledFor: "asc" },
    take: ctx.budget,
    include: {
      contact: { select: { id: true, email: true, fullName: true, title: true, business: { select: { name: true } } } },
      step: { select: { subject: true, bodyMarkdown: true } },
    },
  });

  let sent = 0;
  for (const s of due) {
    if (!s.step || !s.contact) continue;

    // GUARDRAIL #4 — re-check suppression immediately before the send.
    if (isSuppressed(s.contact.email, campaign.brandId, suppressions)) {
      await db.coldSend.update({ where: { id: s.id }, data: { status: "SUPPRESSED" } });
      continue;
    }

    // Per-inbox daily cap: stop (leave the rest QUEUED for the next window/day).
    if (sentToday >= cap) break;

    const token = openTrackingToken(s.id);
    const msg = buildMessage({
      identity,
      step: s.step,
      contact: s.contact,
      sendId: s.id,
      footerDisclosure: ctx.footerDisclosure,
      track: true,
    });

    try {
      const res = await ctx.transport.send(msg);
      await db.coldSend.update({
        where: { id: s.id },
        data: { status: "SENT", sentAt: new Date(), messageId: res.messageId ?? null, trackingToken: token, error: null },
      });
      await db.emailEvent.create({ data: { sendId: s.id, type: "SENT" } });
      sentToday++;
      sent++;
    } catch (err) {
      const error = String((err as Error)?.message ?? err).slice(0, 500);
      await db.coldSend.update({ where: { id: s.id }, data: { status: "FAILED", error, trackingToken: token } });
      await db.emailEvent.create({ data: { sendId: s.id, type: "FAILED", meta: error } });
      await logEvent("error", "coldemail.send.fail", { campaignId: campaign.id, sendId: s.id, error });
    }

    await sleep(jitter());
  }
  return sent;
}

/** Mark a campaign DONE once nothing is left QUEUED (all sends terminal). */
async function maybeCompleteCampaign(campaignId: string): Promise<void> {
  const remaining = await db.coldSend.count({ where: { campaignId, status: "QUEUED" } });
  if (remaining > 0) return;
  const any = await db.coldSend.count({ where: { campaignId } });
  if (any === 0) return; // nothing was ever scheduled — leave it SENDING
  await db.coldCampaign.update({ where: { id: campaignId }, data: { status: "DONE" } });
}

/**
 * The send sweep. GATED by `cold_email_sending_enabled` — the single line that
 * keeps everything below inert until a human enables sending on prod.
 */
export async function coldEmailSendSweep(): Promise<void> {
  // ===== GUARDRAIL #1 — MASTER KILL-SWITCH =====
  if (!(await getSettingBool("cold_email_sending_enabled", false))) return;

  let campaigns: CampaignForSend[];
  try {
    campaigns = await db.coldCampaign.findMany({
      where: { status: "SENDING" },
      select: {
        id: true,
        brandId: true,
        listId: true,
        launchedAt: true,
        sendWindowStart: true,
        sendWindowEnd: true,
        timezone: true,
      },
    });
  } catch {
    // Table not migrated on this environment yet — no-op (mirrors marketing sweep).
    return;
  }
  if (campaigns.length === 0) return;

  const protectedSet = protectedDomainSet(await getSetting("cold_email_protected_domains"), appHost());
  const ceiling = getSettingIntSafe(await getSetting("coldemail_warmup_ceiling"), 40);
  const warmupEnabled = (await getSetting("coldemail_warmup_enabled")) !== "false";
  const footerDisclosure = await getSetting("coldemail_footer_disclosure");
  const now = new Date();

  let transport: MailTransport;
  try {
    transport = await getTransport("nxeon-smtp");
  } catch (err) {
    await logEvent("error", "coldemail.transport.init", { message: String(err) });
    return;
  }

  let budget = MAX_SENDS_PER_SWEEP;
  for (const campaign of campaigns) {
    if (budget <= 0) break;

    const brand = await db.brand.findUnique({ where: { id: campaign.brandId } });
    if (!brand) continue;

    // ===== GUARDRAILS #2 + #3 — reputation isolation + per-brand gate =====
    const eligibility = evaluateSendEligibility(brand, protectedSet);
    if (!eligibility.eligible) {
      await logEvent("warn", "coldemail.send.brand_blocked", {
        campaignId: campaign.id,
        brandId: brand.id,
        reasons: eligibility.reasons,
      });
      continue;
    }

    const identity: SendIdentity = {
      id: brand.id,
      name: brand.name,
      fromName: brand.fromName,
      fromEmail: brand.fromEmail,
      replyTo: brand.replyTo,
      sendingDomain: brand.sendingDomain,
      physicalPostalAddress: brand.physicalPostalAddress,
    };

    try {
      await scheduleCampaignSends(campaign);
      const sent = await processDueSends(campaign, identity, {
        now,
        transport,
        ceiling,
        warmupEnabled,
        footerDisclosure,
        budget,
      });
      budget -= sent;
      await maybeCompleteCampaign(campaign.id);
    } catch (err) {
      await logEvent("error", "coldemail.send.campaign", { campaignId: campaign.id, message: String(err) });
    }
  }
}

function getSettingIntSafe(raw: string, fallback: number): number {
  const n = Number(raw);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : fallback;
}

