import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { verifyOpenToken } from "@/lib/coldemail/compliance";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";

/**
 * Open-tracking pixel. Verifies the HMAC token, records an OPEN EmailEvent for the
 * send, and always returns a 1x1 transparent GIF (even on a bad token) so a broken
 * or replayed link never shows a broken-image icon in a recipient's inbox.
 *
 * Never throws, never blocks: a tracking write failing must not fail the pixel.
 */

// 1x1 transparent GIF.
const PIXEL = Buffer.from("R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7", "base64");

function gif(): Response {
  return new NextResponse(new Uint8Array(PIXEL), {
    status: 200,
    headers: {
      "Content-Type": "image/gif",
      "Content-Length": String(PIXEL.length),
      "Cache-Control": "no-store, no-cache, must-revalidate, private",
      Pragma: "no-cache",
    },
  });
}

export async function GET(_req: Request, { params }: { params: Promise<{ token: string }> }) {
  const { token } = await params;
  const sendId = verifyOpenToken(token);
  if (sendId) {
    try {
      const send = await db.coldSend.findUnique({ where: { id: sendId }, select: { id: true } });
      if (send) await db.emailEvent.create({ data: { sendId, type: "OPEN" } });
    } catch {
      /* tracking is best-effort — always return the pixel */
    }
  }
  return gif();
}

import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { verifyClickToken } from "@/lib/coldemail/compliance";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";

/**
 * Click-tracking redirect. The destination URL is carried INSIDE the HMAC-signed
 * token (see clickTrackingToken), so an attacker cannot turn this into an open
 * redirect by swapping the target — an unsigned/tampered token 400s instead of
 * redirecting. verifyClickToken additionally requires an absolute http(s) URL.
 *
 * On a valid token it records a CLICK EmailEvent (best-effort) then 302s to the
 * real destination.
 */
export async function GET(_req: Request, { params }: { params: Promise<{ token: string }> }) {
  const { token } = await params;
  const claims = verifyClickToken(token);
  if (!claims) {
    return NextResponse.json({ error: "Invalid or expired link." }, { status: 400 });
  }
  try {
    const send = await db.coldSend.findUnique({ where: { id: claims.sendId }, select: { id: true } });
    if (send) await db.emailEvent.create({ data: { sendId: claims.sendId, type: "CLICK", meta: claims.url.slice(0, 300) } });
  } catch {
    /* tracking is best-effort — still redirect */
  }
  return NextResponse.redirect(claims.url, 302);
}

import { NextResponse } from "next/server";
import { recordFeedback, type FeedbackKind } from "@/lib/coldemail/feedback";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";

/**
 * Inbound bounce / complaint webhook SEAM (Phase 2).
 *
 * This is the single choke point a real feedback source wires into later — SES
 * SNS notifications (Bounce/Complaint) or a Mailcow FBL forwarder. No live IMAP
 * polling this phase; the plumbing (suppression + circuit breaker) is done and
 * reached through `recordFeedback`, so enabling a source is a routing change here.
 *
 * PROTECTED by a shared secret. Set `COLDEMAIL_FEEDBACK_SECRET` and send it as
 * `Authorization: Bearer <secret>` (or `?secret=`). With no secret configured the
 * endpoint refuses everything — it never processes unauthenticated feedback.
 *
 * Body: { "email": "...", "kind": "BOUNCE" | "COMPLAINT", "note"?: "..." }
 */
export async function POST(req: Request) {
  const secret = process.env.COLDEMAIL_FEEDBACK_SECRET;
  if (!secret) {
    return NextResponse.json({ error: "Feedback endpoint disabled — no secret configured." }, { status: 503 });
  }
  const auth = req.headers.get("authorization") ?? "";
  const bearer = auth.startsWith("Bearer ") ? auth.slice(7) : "";
  const qs = new URL(req.url).searchParams.get("secret") ?? "";
  if (bearer !== secret && qs !== secret) {
    return NextResponse.json({ error: "Unauthorized." }, { status: 401 });
  }

  let body: { email?: string; kind?: string; note?: string };
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON." }, { status: 400 });
  }

  const email = String(body.email ?? "").trim();
  const kindRaw = String(body.kind ?? "").toUpperCase();
  if (!email) return NextResponse.json({ error: "Missing email." }, { status: 400 });
  if (kindRaw !== "BOUNCE" && kindRaw !== "COMPLAINT") {
    return NextResponse.json({ error: "kind must be BOUNCE or COMPLAINT." }, { status: 400 });
  }

  const result = await recordFeedback(email, kindRaw as FeedbackKind, { note: body.note });
  return NextResponse.json(result, { status: result.ok ? 200 : 422 });
}

