import {
  isSuppressed,
  requireBrandCompliance,
  evaluateSendEligibility,
  protectedDomainSet,
  normalizeEmail,
  type SuppressionLike,
} from "@/lib/coldemail/compliance";
import { getSetting } from "@/lib/settings";
import { recordFeedback, clearCircuitBreaker } from "@/lib/coldemail/feedback";

// ---------------------------------------------------------------------------
// Campaign lifecycle (Phase 2) — launch / pause / schedule
//
// Launching only flips a campaign to SENDING; the worker (worker/coldemail.ts)
// does the scheduling + sending, and only while the master kill-switch
// `cold_email_sending_enabled` is on. So even a launched campaign sends NOTHING
// until a human enables sending on prod.
// ---------------------------------------------------------------------------

function appHost(): string | null {
  try {
    return process.env.APP_URL ? new URL(process.env.APP_URL).host : null;
  } catch {
    return null;
  }
}

/** The full send-eligibility verdict for a brand, using the live protected set. */
async function brandEligibility(brand: Parameters<typeof evaluateSendEligibility>[0]) {
  const set = protectedDomainSet(await getSetting("cold_email_protected_domains"), appHost());
  return evaluateSendEligibility(brand, set);
}

/**
 * Launch a campaign: set status SENDING + stamp launchedAt. REFUSES if the brand
 * is not send-eligible (compliance, reputation isolation, or circuit-breaker
 * pause) — the same gate the worker enforces, surfaced with reasons.
 */
export async function launchCampaign(campaignId: string): Promise<ActionState> {
  await requireArea("platform");
  const campaign = await db.coldCampaign.findUnique({
    where: { id: campaignId },
    include: { brand: true, _count: { select: { steps: true } } },
  });
  if (!campaign) return { error: "Campaign not found." };
  if (campaign._count.steps === 0) return { error: "Add at least one sequence step before launching." };

  const eligibility = await brandEligibility(campaign.brand);
  if (!eligibility.eligible) {
    return { error: `Cannot launch — the brand is not eligible to send: ${eligibility.reasons.join("; ")}` };
  }

  await db.coldCampaign.update({
    where: { id: campaignId },
    // Preserve an earlier launchedAt on resume so scheduling stays stable.
    data: { status: "SENDING", launchedAt: campaign.launchedAt ?? new Date() },
  });
  await logEvent("info", "coldemail.campaign.launch", { campaignId });
  revalidatePath(`/admin/coldemail/campaigns/${campaignId}`);
  revalidatePath("/admin/coldemail/campaigns");
  revalidatePath("/admin/coldemail");
  return { ok: true };
}

/** Pause a SENDING campaign — the worker skips PAUSED campaigns entirely. */
export async function pauseCampaign(campaignId: string): Promise<ActionState> {
  await requireArea("platform");
  await db.coldCampaign.update({ where: { id: campaignId }, data: { status: "PAUSED" } }).catch(() => null);
  revalidatePath(`/admin/coldemail/campaigns/${campaignId}`);
  revalidatePath("/admin/coldemail/campaigns");
  return { ok: true };
}

/** Resume a PAUSED/SCHEDULED campaign back to SENDING (re-checks eligibility). */
export async function resumeCampaign(campaignId: string): Promise<ActionState> {
  return launchCampaign(campaignId);
}

/** Minutes-from-midnight for an "HH:MM" string, or null if blank/invalid. */
function parseHhmm(v: string): number | null {
  const m = /^(\d{1,2}):(\d{2})$/.exec(v.trim());
  if (!m) return null;
  const h = Number(m[1]);
  const min = Number(m[2]);
  if (h > 23 || min > 59) return null;
  return h * 60 + min;
}

/** Set a campaign's send window + timezone (both optional). */
export async function scheduleCampaign(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");
  const campaignId = String(formData.get("campaignId") ?? "").trim();
  if (!campaignId) return { error: "Missing campaign." };
  const startRaw = String(formData.get("sendWindowStart") ?? "").trim();
  const endRaw = String(formData.get("sendWindowEnd") ?? "").trim();
  const timezone = String(formData.get("timezone") ?? "UTC").trim().slice(0, 64) || "UTC";

  const sendWindowStart = startRaw ? parseHhmm(startRaw) : null;
  const sendWindowEnd = endRaw ? parseHhmm(endRaw) : null;
  if ((startRaw && sendWindowStart === null) || (endRaw && sendWindowEnd === null)) {
    return { error: "Send window times must be HH:MM (24-hour)." };
  }
  // Both or neither — a one-sided window is ambiguous.
  if ((sendWindowStart === null) !== (sendWindowEnd === null)) {
    return { error: "Set both a start and an end time, or leave both blank." };
  }

  await db.coldCampaign.update({
    where: { id: campaignId },
    data: { sendWindowStart, sendWindowEnd, timezone },
  });
  revalidatePath(`/admin/coldemail/campaigns/${campaignId}`);
  return { ok: true };
}

// ---------------------------------------------------------------------------
// Bounce / complaint (manual entry + circuit-breaker controls)
// ---------------------------------------------------------------------------

/** Manually record a bounce or complaint → GLOBAL suppression (+ breaker). */
export async function reportFeedback(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");
  const email = String(formData.get("email") ?? "").trim();
  const kindRaw = String(formData.get("kind") ?? "").toUpperCase();
  if (!email || !emailSchema.safeParse(email).success) return { error: "Enter a valid email address." };
  if (kindRaw !== "BOUNCE" && kindRaw !== "COMPLAINT") return { error: "Pick bounce or complaint." };
  const res = await recordFeedback(email, kindRaw as "BOUNCE" | "COMPLAINT", { note: "manual admin entry" });
  revalidatePath("/admin/coldemail/suppression");
  revalidatePath("/admin/coldemail/brands");
  if (!res.ok) return { error: "Could not record the feedback." };
  return { ok: true, error: `Recorded ${kindRaw.toLowerCase()} and suppressed ${email}.${res.brandPaused ? " Brand auto-paused by the circuit breaker." : ""}` };
}

/** Clear a brand's circuit-breaker pause after cleanup. */
export async function clearBrandPause(brandId: string): Promise<ActionState> {
  await requireArea("platform");
  await clearCircuitBreaker(brandId).catch(() => null);
  revalidatePath("/admin/coldemail/brands");
  revalidatePath("/admin/coldemail");
  return { ok: true };
}

