export function CampaignLaunchControls({
  campaignId,
  status,
  eligible,
  reasons,
  sendingEnabled,
}: {
  campaignId: string;
  status: string;
  eligible: boolean;
  reasons: string[];
  sendingEnabled: boolean;
}) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const act = (fn: () => Promise<State>) =>
    start(async () => {
      setError(null);
      const r = await fn();
      if (r?.error) setError(r.error);
    });

  const isSending = status === "SENDING";
  const isDone = status === "DONE";

  return (
    <div className="space-y-3">
      {!sendingEnabled && (
        <div className="rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
          Global sending is disabled — launching queues the campaign, but nothing goes out until an operator
          enables sending in Settings.
        </div>
      )}
      {!eligible && (
        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-300">
          <p className="font-medium">Brand is not eligible to send:</p>
          <ul className="mt-1 list-disc space-y-0.5 pl-5">
            {reasons.map((r) => (
              <li key={r}>{r}</li>
            ))}
          </ul>
        </div>
      )}
      {error && (
        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">{error}</div>
      )}
      <div className="flex flex-wrap items-center gap-2">
        {!isSending && !isDone && (
          <button
            className="btn-primary"
            disabled={pending || !eligible}
            onClick={() => act(() => (status === "PAUSED" ? resumeCampaign(campaignId) : launchCampaign(campaignId)))}
          >
            {pending ? "Working…" : status === "PAUSED" ? "Resume sending" : "Launch campaign"}
