import Link from "next/link";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { getSetting, getSettingBool } from "@/lib/settings";
import { PageHeader, Badge } from "@/components/ui/primitives";
import {
  evaluateSendEligibility,
  protectedDomainSet,
  effectiveDailyCap,
  warmupDayIndex,
} from "@/lib/coldemail/compliance";
import {
  SequenceStepForm,
  SequenceStepDelete,
  CampaignPreview,
  CampaignLaunchControls,
  CampaignScheduleForm,
} from "@/components/admin/coldemail/Controls";

export const dynamic = "force-dynamic";

function appHost(): string | null {
  try {
    return process.env.APP_URL ? new URL(process.env.APP_URL).host : null;
  } catch {
    return null;
  }
}

function hhmm(mins: number | null): string {
  if (mins == null) return "";
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
}

function startOfUtcDay(now = new Date()): Date {
  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
}

export default async function ColdEmailCampaignDetail({ params }: { params: Promise<{ id: string }> }) {
  await requireArea("platform");
  const { id } = await params;

  const campaign = await db.coldCampaign.findUnique({
    where: { id },
    include: {
      brand: true,
      list: { select: { name: true, _count: { select: { members: true } } } },
      steps: { orderBy: { stepOrder: "asc" } },
    },
  });
  if (!campaign) notFound();

  const [
    protectedRaw,
    sendingEnabled,
    warmupEnabled,
    warmupCeiling,
    statusGroups,
    opened,
    clicked,
    bounced,
    sentToday,
  ] = await Promise.all([
    getSetting("cold_email_protected_domains"),
    getSettingBool("cold_email_sending_enabled"),
    getSettingBool("coldemail_warmup_enabled"),
    getSetting("coldemail_warmup_ceiling"),
    db.coldSend.groupBy({ by: ["status"], where: { campaignId: id }, _count: true }),
    db.emailEvent.count({ where: { type: "OPEN", send: { campaignId: id } } }),
    db.emailEvent.count({ where: { type: "CLICK", send: { campaignId: id } } }),
    db.emailEvent.count({ where: { type: "BOUNCE", send: { campaignId: id } } }),
    db.coldSend.count({ where: { campaign: { brandId: campaign.brandId }, sentAt: { gte: startOfUtcDay() } } }),
  ]);

  const eligibility = evaluateSendEligibility(campaign.brand, protectedDomainSet(protectedRaw, appHost()));
  const statusCount = (s: string) => statusGroups.find((g) => g.status === s)?._count ?? 0;
  const ceiling = campaign.brand.dailySendCap ?? (Number(warmupCeiling) || 40);
  const todayCap = effectiveDailyCap({
    warmupStartedAt: campaign.brand.warmupStartedAt,
    ceiling,
    warmupEnabled,
  });
  const warmupDay = warmupDayIndex(campaign.brand.warmupStartedAt) + 1;

  const stats: { label: string; value: number; tone: "slate" | "green" | "red" | "amber" | "brand" }[] = [
    { label: "Queued", value: statusCount("QUEUED"), tone: "slate" },
    { label: "Sent", value: statusCount("SENT"), tone: "green" },
    { label: "Opened", value: opened, tone: "brand" },
    { label: "Clicked", value: clicked, tone: "brand" },
    { label: "Bounced", value: bounced, tone: "red" },
    { label: "Suppressed", value: statusCount("SUPPRESSED"), tone: "amber" },
    { label: "Failed", value: statusCount("FAILED"), tone: "red" },
  ];
  const toneClass: Record<string, string> = {
    slate: "text-slate-200",
    green: "text-emerald-300",
    red: "text-red-300",
    amber: "text-amber-300",
    brand: "text-brand-300",
  };

  return (
    <div className="space-y-6">
      <PageHeader title={campaign.name} sub={`${campaign.brand.name} → ${campaign.list.name}`}>
        <Link href="/admin/coldemail/campaigns" className="btn-ghost px-3 py-1.5 text-sm">
          Back to campaigns
        </Link>
      </PageHeader>

      <div className="grid gap-4 sm:grid-cols-3">
        <div className="card p-4">
          <p className="text-[13px] text-slate-400">Status</p>
          <div className="mt-1.5">
            <Badge tone="slate">{campaign.status.toLowerCase()}</Badge>
          </div>
        </div>
        <div className="card p-4">
          <p className="text-[13px] text-slate-400">Recipients on list</p>
          <p className="mt-1.5 text-2xl font-bold">{campaign.list._count.members}</p>
        </div>
        <div className="card p-4">
          <p className="text-[13px] text-slate-400">Sequence steps</p>
          <p className="mt-1.5 text-2xl font-bold">{campaign.steps.length}</p>
        </div>
      </div>

      {/* Launch / pause / resume */}
      <div className="card">
        <p className="section-label mb-4">Sending controls</p>
        <CampaignLaunchControls
          campaignId={campaign.id}
          status={campaign.status}
          eligible={eligibility.eligible}
          reasons={eligibility.reasons}
          sendingEnabled={sendingEnabled}
        />
      </div>

      {/* Live stats */}
      <div className="card">
        <p className="section-label mb-4">Live stats</p>
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-4 lg:grid-cols-7">
          {stats.map((s) => (
            <div key={s.label} className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-3">
              <p className="text-[12px] text-slate-400">{s.label}</p>
              <p className={`mt-1 text-xl font-bold ${toneClass[s.tone]}`}>{s.value}</p>
            </div>
          ))}
        </div>
        <div className="mt-4 flex flex-wrap items-center gap-4 border-t border-white/[0.06] pt-4 text-xs text-slate-400">
          <span>
            Warmup: {campaign.brand.warmupStartedAt ? `day ${warmupDay}` : "not started"} · today's per-inbox cap{" "}
            <span className="font-semibold text-slate-200">{todayCap}</span> · sent today (brand){" "}
            <span className="font-semibold text-slate-200">{sentToday}</span>
          </span>
        </div>
      </div>

      {/* Schedule */}
      <div className="card">
        <p className="section-label mb-4">Send window</p>
        <CampaignScheduleForm
          campaignId={campaign.id}
          sendWindowStart={hhmm(campaign.sendWindowStart)}
          sendWindowEnd={hhmm(campaign.sendWindowEnd)}
          timezone={campaign.timezone}
        />
      </div>

      <div className="card">
        <p className="section-label mb-4">Preview / dry-run</p>
        <CampaignPreview campaignId={campaign.id} />
      </div>

      <div className="card">
        <p className="section-label mb-4">Sequence</p>
        {campaign.steps.length === 0 ? (
          <p className="mb-4 text-sm text-slate-500">No steps yet — add the first message below.</p>
        ) : (
          <ol className="mb-6 space-y-3">
            {campaign.steps.map((s) => (
              <li key={s.id} className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-4">
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <div className="flex items-center gap-2">
                      <Badge tone="brand">Step {s.stepOrder}</Badge>
                      <span className="text-xs text-slate-500">
                        {s.delayDays === 0 ? "sent immediately" : `+${s.delayDays} day(s)`}
                      </span>
                    </div>
                    <p className="mt-2 font-medium text-white">{s.subject}</p>
                    <pre className="mt-1 whitespace-pre-wrap font-sans text-sm text-slate-400">{s.bodyMarkdown}</pre>
                  </div>
                  <SequenceStepDelete id={s.id} />
                </div>
              </li>
            ))}
          </ol>
        )}
        <div className="border-t border-white/[0.06] pt-4">
          <p className="section-label mb-3">Add a step</p>
          <SequenceStepForm campaignId={campaign.id} />
        </div>
      </div>
    </div>
  );
}

import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { getSetting } from "@/lib/settings";
import { PageHeader, Badge, EmptyState } from "@/components/ui/primitives";
import { BrandForm, BrandDelete, ClearBrandPauseButton } from "@/components/admin/coldemail/Controls";
import { evaluateSendEligibility, protectedDomainSet } from "@/lib/coldemail/compliance";

export const dynamic = "force-dynamic";

function appHost(): string | null {
  try {
    return process.env.APP_URL ? new URL(process.env.APP_URL).host : null;
  } catch {
    return null;
  }
}

export default async function ColdEmailBrands() {
  await requireArea("platform");

  const [brands, protectedRaw] = await Promise.all([
    db.brand.findMany({ orderBy: { createdAt: "asc" } }),
    getSetting("cold_email_protected_domains"),
  ]);
  const protectedSet = protectedDomainSet(protectedRaw, appHost());

  return (
    <div className="space-y-6">
      <PageHeader
        title="Brands"
        sub="Sending identities. A brand may only send with a physical address, verified SPF/DKIM/DMARC, and a dedicated (non-platform) sending domain."
      />

      <div className="card">
        <p className="section-label mb-4">Add a brand</p>
        <BrandForm />
      </div>

      {brands.length === 0 ? (
        <EmptyState title="No brands yet" sub="Add a sending identity above." />
      ) : (
        <div className="space-y-4">
          {brands.map((b) => {
            const elig = evaluateSendEligibility(b, protectedSet);
            return (
              <div key={b.id} className="card">
                <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
                  <div className="flex items-center gap-2">
                    <span className="font-medium text-white">{b.name}</span>
                    {elig.eligible ? (
                      <Badge tone="green">eligible to send</Badge>
                    ) : (
                      <Badge tone="red">not eligible</Badge>
                    )}
                    {b.sendingPaused && <Badge tone="amber">paused</Badge>}
                  </div>
                  <div className="flex items-center gap-2">
                    {b.sendingPaused && <ClearBrandPauseButton brandId={b.id} />}
                    <BrandDelete id={b.id} />
                  </div>
                </div>

                {/* Send-eligibility checklist */}
                <div className="mb-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-5">
                  {elig.checks.map((c) => (
                    <div
                      key={c.key}
                      className={`flex items-center gap-2 rounded-lg border px-3 py-2 text-xs ${
                        c.ok
                          ? "border-emerald-500/30 bg-emerald-500/[0.06] text-emerald-300"
                          : "border-red-500/30 bg-red-500/[0.06] text-red-300"
                      }`}
                    >
                      <span aria-hidden>{c.ok ? "●" : "○"}</span>
                      <span>{c.label}</span>
                    </div>
                  ))}
                </div>
                {b.sendingPaused && b.pausedReason && (
                  <p className="mb-4 rounded-lg border border-amber-500/30 bg-amber-500/[0.06] px-3 py-2 text-xs text-amber-300">
                    {b.pausedReason}
                  </p>
                )}

                <BrandForm
                  brand={{
                    id: b.id,
                    name: b.name,
                    fromName: b.fromName,
                    fromEmail: b.fromEmail,
                    sendingDomain: b.sendingDomain,
                    physicalPostalAddress: b.physicalPostalAddress,
                    replyTo: b.replyTo,
                    spfVerified: b.spfVerified,
                    dkimVerified: b.dkimVerified,
                    dmarcVerified: b.dmarcVerified,
                  }}
                />
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

