import { test } from "node:test";
import assert from "node:assert/strict";

// Tokens + message rendering sign with AUTH_SECRET; set a deterministic one.
process.env.AUTH_SECRET = process.env.AUTH_SECRET || "test-secret-for-coldemail";
process.env.APP_URL = process.env.APP_URL || "https://nxeon.cloud";

import {
  isSuppressed,
  isProtectedDomain,
  protectedDomainSet,
  normalizeDomain,
  evaluateSendEligibility,
  effectiveDailyCap,
  warmupDailyCap,
  warmupDayIndex,
  dailyCapOk,
  openTrackingToken,
  verifyOpenToken,
  clickTrackingToken,
  verifyClickToken,
  DEFAULT_DAILY_CAP,
  type SuppressionLike,
} from "../lib/coldemail/compliance.ts";
import { buildMessage, markdownToHtml, injectTracking, identityDomain } from "../lib/coldemail/sender.ts";

const compliantBrand = {
  id: "brand-1",
  name: "Nxeon Outreach",
  fromName: "Nxeon",
  fromEmail: "hello@outreach.example.com",
  replyTo: "reply@outreach.example.com",
  sendingDomain: "outreach.example.com",
  physicalPostalAddress: "1 Main St, Wilmington, DE 19801, USA",
  spfVerified: true,
  dkimVerified: true,
  dmarcVerified: true,
  sendingPaused: false,
};

const contact = {
  id: "contact-1",
  email: "jane@acme.com",
  fullName: "Jane Doe",
  title: "Head of Marketing",
  business: { name: "Acme Studios" },
};

const step = {
  subject: "Quick question about {{company}}",
  bodyMarkdown: "Hi {{firstName}},\n\nI noticed **{{company}}** and wanted to reach out. See [our site](https://example.com/pricing).",
};

// ---------------------------------------------------------------------------
// Reputation isolation — protected-domain refusal
// ---------------------------------------------------------------------------

test("normalizeDomain strips protocol, path, port and @local-part", () => {
  assert.equal(normalizeDomain("https://Mail.Nxeon.Cloud/inbox"), "mail.nxeon.cloud");
  assert.equal(normalizeDomain("user@Bulk.Nxeon.Cloud"), "bulk.nxeon.cloud");
  assert.equal(normalizeDomain("example.com:587"), "example.com");
});

test("protectedDomainSet always includes nxeon.cloud + app host", () => {
  const set = protectedDomainSet("extra.com", "app.example.com");
  assert.ok(set.has("nxeon.cloud"));
  assert.ok(set.has("mail.nxeon.cloud"));
  assert.ok(set.has("app.example.com"));
  assert.ok(set.has("extra.com"));
});

test("isProtectedDomain blocks the apex, its subdomains, and empty domains", () => {
  const set = protectedDomainSet("", "nxeon.cloud");
  assert.equal(isProtectedDomain("nxeon.cloud", set), true);
  assert.equal(isProtectedDomain("bulk.nxeon.cloud", set), true); // subdomain of a protected apex
  assert.equal(isProtectedDomain("", set), true); // no domain → refuse, never fail open
  assert.equal(isProtectedDomain("outreach.example.com", set), false);
});

test("evaluateSendEligibility REFUSES a brand sending from a protected domain", () => {
  const set = protectedDomainSet("", "nxeon.cloud");
  const brand = { ...compliantBrand, sendingDomain: "nxeon.cloud", fromEmail: "x@nxeon.cloud" };
  const verdict = evaluateSendEligibility(brand, set);
  assert.equal(verdict.eligible, false);
  assert.ok(verdict.reasons.some((r) => /protected/i.test(r)));
  assert.equal(verdict.checks.find((c) => c.key === "notProtected")?.ok, false);
});

test("evaluateSendEligibility passes a fully-configured dedicated-domain brand", () => {
  const set = protectedDomainSet("", "nxeon.cloud");
  const verdict = evaluateSendEligibility(compliantBrand, set);
  assert.equal(verdict.eligible, true);
  assert.deepEqual(verdict.reasons, []);
  assert.ok(verdict.checks.every((c) => c.ok));
});

test("evaluateSendEligibility fails a paused brand and a non-compliant brand", () => {
  const set = protectedDomainSet("", "nxeon.cloud");
  assert.equal(evaluateSendEligibility({ ...compliantBrand, sendingPaused: true }, set).eligible, false);
  assert.equal(evaluateSendEligibility({ ...compliantBrand, physicalPostalAddress: "" }, set).eligible, false);
  assert.equal(evaluateSendEligibility({ ...compliantBrand, dkimVerified: false }, set).eligible, false);
});

// ---------------------------------------------------------------------------
// Send-time suppression skip
// ---------------------------------------------------------------------------

test("send-time suppression: a suppressed recipient is detected before send", () => {
  const rows: SuppressionLike[] = [{ email: "jane@acme.com", scope: "GLOBAL", brandId: null }];
  assert.equal(isSuppressed(contact.email, compliantBrand.id, rows), true);
  // Domain-level suppression also catches the recipient.
  const domainRows: SuppressionLike[] = [{ domain: "acme.com", scope: "GLOBAL", brandId: null }];
  assert.equal(isSuppressed(contact.email, compliantBrand.id, domainRows), true);
  // A different address is not suppressed.
  assert.equal(isSuppressed("someone@other.com", compliantBrand.id, rows), false);
});

// ---------------------------------------------------------------------------
// Daily-cap + warmup math
// ---------------------------------------------------------------------------

test("warmupDailyCap ramps day1=5, +5/day, capped at the ceiling", () => {
  assert.equal(warmupDailyCap(0, 40), 5); // day 1
  assert.equal(warmupDailyCap(1, 40), 10); // day 2
  assert.equal(warmupDailyCap(3, 40), 20); // day 4
  assert.equal(warmupDailyCap(7, 40), 40); // day 8 hits ceiling
  assert.equal(warmupDailyCap(20, 40), 40); // never exceeds ceiling
  assert.equal(warmupDailyCap(0, 0), 5); // non-positive ceiling → safe default, ramps normally
});

test("warmupDayIndex is 0 on day one and null start, grows by whole days", () => {
  const start = new Date("2026-08-01T00:00:00Z");
  assert.equal(warmupDayIndex(null), 0);
  assert.equal(warmupDayIndex(start, new Date("2026-08-01T12:00:00Z")), 0);
  assert.equal(warmupDayIndex(start, new Date("2026-08-04T00:00:00Z")), 3);
  assert.equal(warmupDayIndex(start, new Date("2026-07-30T00:00:00Z")), 0); // clock skew clamps to 0
});

test("effectiveDailyCap uses the ramp when warmup is on, flat ceiling when off", () => {
  const start = new Date(Date.now() - 3 * 86_400_000); // day 4 → cap 20
  assert.equal(effectiveDailyCap({ warmupStartedAt: start, ceiling: 40, warmupEnabled: true }), 20);
  assert.equal(effectiveDailyCap({ warmupStartedAt: start, ceiling: 40, warmupEnabled: false }), 40);
  // No warmup start = still on day 1 = 5, never uncapped.
  assert.equal(effectiveDailyCap({ warmupStartedAt: null, ceiling: 40, warmupEnabled: true }), 5);
});

test("dailyCapOk still gates at the ceiling", () => {
  assert.equal(dailyCapOk(4, 5), true);
  assert.equal(dailyCapOk(5, 5), false);
  assert.equal(dailyCapOk(DEFAULT_DAILY_CAP, 0), false);
});

// ---------------------------------------------------------------------------
// Message rendering — footer + List-Unsubscribe headers (RFC 8058)
// ---------------------------------------------------------------------------

test("buildMessage injects the compliance footer (postal address + unsubscribe)", () => {
  const msg = buildMessage({ identity: compliantBrand, step, contact, base: "https://nxeon.cloud" });
  assert.match(msg.html, /1 Main St, Wilmington, DE 19801, USA/);
  assert.match(msg.html, /\/api\/coldemail\/unsubscribe\?token=/);
  assert.match(msg.text, /1 Main St, Wilmington/);
  assert.match(msg.text, /unsubscribe/i);
});

test("buildMessage sets List-Unsubscribe + List-Unsubscribe-Post headers (RFC 8058)", () => {
  const msg = buildMessage({ identity: compliantBrand, step, contact, base: "https://nxeon.cloud" });
  assert.ok(msg.headers["List-Unsubscribe"].startsWith("<https://nxeon.cloud/api/coldemail/unsubscribe?token="));
  assert.equal(msg.headers["List-Unsubscribe-Post"], "List-Unsubscribe=One-Click");
});

test("buildMessage renders From/subject and substitutes personalization tokens", () => {
  const msg = buildMessage({ identity: compliantBrand, step, contact, base: "https://nxeon.cloud" });
  assert.equal(msg.from, "Nxeon <hello@outreach.example.com>");
  assert.equal(msg.to, "jane@acme.com");
  assert.equal(msg.subject, "Quick question about Acme Studios");
  assert.match(msg.html, /Hi Jane/); // {{firstName}}
  assert.match(msg.html, /Acme Studios/); // {{company}}
});

test("previews do NOT inject tracking; a tracked send DOES", () => {
  const preview = buildMessage({ identity: compliantBrand, step, contact, base: "https://nxeon.cloud" });
  assert.doesNotMatch(preview.html, /\/api\/coldemail\/track\//);

  const tracked = buildMessage({
    identity: compliantBrand,
    step,
    contact,
    sendId: "send-1",
    base: "https://nxeon.cloud",
    track: true,
  });
  assert.match(tracked.html, /\/api\/coldemail\/track\/open\//); // open pixel
  assert.match(tracked.html, /\/api\/coldemail\/track\/click\//); // wrapped link
  // The unsubscribe link is never routed through click-tracking.
  assert.match(tracked.html, /\/api\/coldemail\/unsubscribe\?token=[^"]+"/);
});

test("markdownToHtml escapes HTML and renders links/bold safely", () => {
  const html = markdownToHtml("Hello <script>alert(1)</script> **bold** [x](https://ok.com)");
  assert.doesNotMatch(html, /<script>/);
  assert.match(html, /&lt;script&gt;/);
  assert.match(html, /<strong>bold<\/strong>/);
  assert.match(html, /<a href="https:\/\/ok.com"/);
});

test("injectTracking can be told to skip the unsubscribe link", () => {
  const html = `<a href="https://nxeon.cloud/api/coldemail/unsubscribe?token=abc">unsub</a><a href="https://example.com">x</a>`;
  const out = injectTracking(html, "send-1", "https://nxeon.cloud", {
    skip: (url) => url.includes("/api/coldemail/unsubscribe"),
  });
  assert.match(out, /href="https:\/\/nxeon.cloud\/api\/coldemail\/unsubscribe\?token=abc"/); // untouched
  assert.match(out, /\/api\/coldemail\/track\/click\//); // example.com wrapped
  assert.match(out, /track\/open\//); // pixel appended
});

test("identityDomain prefers the sending domain, falls back to the from address", () => {
  assert.equal(identityDomain(compliantBrand), "outreach.example.com");
  assert.equal(identityDomain({ ...compliantBrand, sendingDomain: "" }), "outreach.example.com");
});

// ---------------------------------------------------------------------------
// Tracking tokens
// ---------------------------------------------------------------------------

test("open token round-trips and rejects tampering", () => {
  const t = openTrackingToken("send-123");
  assert.equal(verifyOpenToken(t), "send-123");
  assert.equal(verifyOpenToken(t.slice(0, -2) + "zz"), null);
  assert.equal(verifyOpenToken("garbage"), null);
});

test("click token carries a signed URL and blocks open-redirect tampering", () => {
  const t = clickTrackingToken("send-123", "https://example.com/pricing");
  const claims = verifyClickToken(t);
  assert.deepEqual(claims, { sendId: "send-123", url: "https://example.com/pricing" });
  // Tampering the token invalidates it (cannot swap the destination).
  assert.equal(verifyClickToken(t.slice(0, -2) + "zz"), null);
});

test("verifyClickToken refuses non-http(s) targets even if signed", () => {
  const t = clickTrackingToken("send-1", "javascript:alert(1)");
  assert.equal(verifyClickToken(t), null);
});
